(window.BUNKAZAI_DETAIL=window.BUNKAZAI_DETAIL||{})["c67"]=[{"id":"00014084","register_sub_id":"101","register_pk":"508344","name":"判屋船越家住宅裏門","kana":"はんやふなこしけじゅうたくうらもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"鳥取県","address":"鳥取県米子市天神町二丁目37他","lat":35.43225556,"lng":133.32531389,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造、瓦葺、間口2.7m","structure_material":"木造","registered":"2021.10.14(令和3.10.14)","register_no":"31 - 0280","desc":"敷地南辺に南面し、東蔵と西蔵の間に建つ棟門。主柱間に両開きの板戸を吊り、内法上は横連子の欄間とする。下段を絵様付とした二段の腕木を伸ばして軒桁を支持し、屋根は桟瓦葺とする。軸部及び軒廻りとも弁柄塗仕上で、小規模ながらも旧家の格式を示す裏門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014084"},{"id":"00014081","register_sub_id":"101","register_pk":"508341","name":"判屋船越家住宅主屋","kana":"はんやふなこしけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"鳥取県","address":"鳥取県米子市天神町二丁目37他","lat":35.43250833,"lng":133.325375,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積337㎡","structure_material":"木造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"31 - 0277","desc":"加茂川に北面する船問屋の主屋。切妻造平入桟瓦葺、東を土間、西を一列四室とし、ナカノマ上部を吹抜とする。西に前庭を設けた一列三室の座敷を落棟で接続する。正面は下屋を付し、一階は大戸と出格子、二階は平格子とする。旧米子城下に残る良質な近代町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014081"},{"id":"00014083","register_sub_id":"101","register_pk":"508343","name":"判屋船越家住宅西蔵","kana":"はんやふなこしけじゅうたくにしぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"鳥取県","address":"鳥取県米子市天神町二丁目37他","lat":35.43228056,"lng":133.32530278,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積30㎡","structure_material":"土蔵造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"31 - 0279","desc":"敷地南辺中央に位置する土蔵。土蔵造二階建、切妻造妻入桟瓦葺の南北棟。切石積基礎に建ち、北面を戸口として下屋を付す。西を除く三方に窓を各一箇所開け、外壁は軒裏まで塗込め漆喰塗仕上。北面は腰と窓下を海鼠壁とする。東蔵と共に敷地を構成する土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014083"},{"id":"00014082","register_sub_id":"101","register_pk":"508342","name":"判屋船越家住宅東蔵","kana":"はんやふなこしけじゅうたくひがしぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"鳥取県","address":"鳥取県米子市天神町二丁目37他","lat":35.43226111,"lng":133.32536667,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積32㎡","structure_material":"土蔵造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"31 - 0278","desc":"敷地南東隅に位置する土蔵。土蔵造二階建、切妻造妻入桟瓦葺の南北棟。切石積基礎に建ち、北面を戸口として下屋を付し、窓を一箇所開ける。外壁は軒裏まで塗込め漆喰塗仕上とする。腰は竪板張とする。敷地外郭の景観をつくる土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014082"},{"id":"00004405","register_sub_id":"101","register_pk":"105395","name":"東門脇家住宅旧味噌蔵","kana":"ひがしかどわきけじゅうたくきゅうみそぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"鳥取県","address":"鳥取県西伯郡大山町所子425","lat":35.48381145,"lng":133.46603745,"geo_status":"db","era":"明治32","year":1899,"year_source":"db","year_min":1899,"year_max":1899,"year_label":null,"structure":"木造2階建、瓦葺、建築面積30㎡","structure_material":"木造2階建","registered":"2004.11.08(平成16.11.08)","register_no":"31 － 0085","desc":"木造２階建，切妻造，平入で，石積基礎上に建つ。規模は桁行２間半梁間２間，東面に扉口２箇所を設け，南妻には庇を架けて作業場をつくる。屋根は桟瓦葺，外壁は漆喰塗で，西壁を横板で覆う。敷地西辺を流れる水路沿いにあり，生活の一端を示す施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004405"},{"id":"00004404","register_sub_id":"101","register_pk":"105394","name":"東門脇家住宅蔵","kana":"ひがしかどわきけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"鳥取県","address":"鳥取県西伯郡大山町所子425","lat":35.48357524,"lng":133.466264,"geo_status":"db","era":"大正7","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積23㎡","structure_material":"土蔵造2階建","registered":"2004.11.08(平成16.11.08)","register_no":"31 － 0084","desc":"土蔵造２階建，切妻造，妻入で，規模は桁行３間梁間２間，北面に庇を付けて観音開扉を構え，２階には小窓を開ける。屋根は石州瓦葺，外壁は漆喰塗で，両側面と背面は横板で覆い，軒には鉢巻を廻す。丁寧なつくりの土蔵で，敷地南西の角地の景観を整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004404"},{"id":"00004819","register_sub_id":"101","register_pk":"105809","name":"東門脇家住宅化粧部屋","kana":"ひがしかどわきけじゅうたくけしょうべや","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"鳥取県","address":"鳥取県西伯郡大山町所子425","lat":35.48363266,"lng":133.46636952,"geo_status":"db","era":"大正7頃","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積15㎡、塀付","structure_material":"木造平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"31 － 0093","desc":"主屋の南方に位置し，南北棟で建つ。桁行２間半梁間２間規模，切妻造，桟瓦葺の木造平屋建で，北側に化粧部屋，南側に浴室・便所を設ける。北西端には主屋南面から延びた中門付庭塀が取り付く。主屋玄関の前庭と，主屋座敷前の庭園とを区画する要素でもある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004819"},{"id":"00004400","register_sub_id":"101","register_pk":"105390","name":"東門脇家住宅主屋","kana":"ひがしかどわきけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"鳥取県","address":"鳥取県西伯郡大山町所子425","lat":35.48375626,"lng":133.46625171,"geo_status":"db","era":"文政元","year":1818,"year_source":"db","year_min":1818,"year_max":1818,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積231㎡","structure_material":"木造平屋建","registered":"2004.11.08(平成16.11.08)","register_no":"31 － 0080","desc":"敷地のほぼ中央に南面して建つ。桁行９間，東西棟の切妻造，桟瓦葺，平屋建で，正面に下屋を付ける。平面は西を土間，東を複雑な構成の居室部とする。棟札から棟梁は国信村の新七等と判明する。建築年代が明確で，当地における江戸後期民家の基準となる事例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004400"},{"id":"00004818","register_sub_id":"101","register_pk":"105808","name":"東門脇家住宅納屋","kana":"ひがしかどわきけじゅうたくなや","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"鳥取県","address":"鳥取県西伯郡大山町所子425","lat":35.48359502,"lng":133.46643441,"geo_status":"db","era":"大正7頃","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積11㎡","structure_material":"木造平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"31 － 0094","desc":"化粧部屋の南東，屋敷地の南東隅に位置し，東西棟で建つ。桁行２間半梁間１間半規模，切妻造，桟瓦葺の木造平屋建で，北面西寄りに出入口を設け，内部は土間とする。敷地南面道路沿いに土蔵・門長屋とともに並び建ち，屋敷南正面の構えを形づくる要素となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004818"},{"id":"00004406","register_sub_id":"101","register_pk":"105396","name":"東門脇家住宅西面土塀","kana":"ひがしかどわきけじゅうたくにしめんどべい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"鳥取県","address":"鳥取県西伯郡大山町所子425","lat":35.4836603,"lng":133.4661457,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"土塀、瓦葺、延長29m、洗場付","structure_material":"土塀","registered":"2004.11.08(平成16.11.08)","register_no":"31 － 0086","desc":"蔵と旧味噌蔵の間，敷地西辺の水路沿いにある。延長約２９ｍの規模で，街路なりに屈曲し，中途の３間分は屋根を一段切り上げて,洗い場を設ける。精緻な石積基礎上に建つ真壁造で，腰を下見板で覆い，桟瓦葺屋根を架ける。豪壮な屋敷の街路景観を整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004406"},{"id":"00004403","register_sub_id":"101","register_pk":"105393","name":"東門脇家住宅門長屋","kana":"ひがしかどわきけじゅうたくもんながや","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"鳥取県","address":"鳥取県西伯郡大山町所子425","lat":35.48358955,"lng":133.466371,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造2階建、瓦葺、建築面積47㎡","structure_material":"木造2階建","registered":"2004.11.08(平成16.11.08)","register_no":"31 － 0083","desc":"敷地南辺の中央に建つ。２階建，切妻造，桟瓦葺で，西に表門を構え，東が表座敷になる。間口３ｍの表門は五平柱を立て内開き板戸をつけ，冠木上に欄間を入れる。表座敷は東端に切妻玄関を付け，真壁造，外壁下見板張とする。豪壮な屋敷に相応しい構成をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004403"},{"id":"00012013","register_sub_id":"101","register_pk":"210954","name":"丸井家住宅主屋","kana":"まるいけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"鳥取県","address":"鳥取県倉吉市越中町2148他","lat":35.431983,"lng":133.816442,"geo_status":"db","era":"大正5年","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造2階建、瓦葺、建築面積93㎡","structure_material":"木造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"31-232","desc":"南北に長い長方形敷地の西北隅に建つ。大正から昭和初期にかけて倉吉の茶道の中心をなした町家の一つ。切妻造二階建で、赤瓦を葺く。西側と東側で棟の位置を違えるが、平面は一体で右に土間を通し、一、二階共五室を配す。数奇屋風の繊細な意匠でまとめる住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012013"},{"id":"00012016","register_sub_id":"101","register_pk":"210957","name":"丸井家住宅茶室","kana":"まるいけじゅうたくちゃしつ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"鳥取県","address":"鳥取県倉吉市越中町2149","lat":35.431999,"lng":133.816535,"geo_status":"db","era":"大正5年","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋建、瓦葺、延長23m","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"31-235","desc":"主屋の東に南面して建つ茶室。京都の茶人平井仁兵衛の茶室の写しと伝える。背面側切妻造、正面側入母屋造の南北棟桟瓦葺で、正面に銅板葺起り屋根の下屋を付す。正面二間、側面二間半の南に茶室四畳半、北に水屋三畳を配す。外壁を赤く塗り、草庵茶室の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012016"},{"id":"00012015","register_sub_id":"101","register_pk":"210956","name":"丸井家住宅土蔵","kana":"まるいけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"鳥取県","address":"鳥取県倉吉市越中町2149","lat":35.431801,"lng":133.816599,"geo_status":"db","era":"大正5年","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積27㎡","structure_material":"土蔵造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"31-234","desc":"敷地南東隅に東西棟で建つ土蔵。二階建、桟瓦葺。敷地側の北面は離れと一連の廊下が庇状に取り付く。正面側は外壁漆喰塗、背面側は一階部分を竪板張、上部漆喰塗とする。内部は上下階共一室で、茶道具や掛け軸などを収蔵したもので、玉川沿いの景観を作る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012015"},{"id":"00012014","register_sub_id":"101","register_pk":"210955","name":"丸井家住宅離れ","kana":"まるいけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"鳥取県","address":"鳥取県倉吉市越中町2148他","lat":35.431794,"lng":133.816536,"geo_status":"db","era":"大正6年","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造2階建、瓦葺、建築面積41㎡","structure_material":"木造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"31-233","desc":"敷地の南端中央、玉川に接して建つ。切妻造二階建、桟瓦葺で、切石積の基礎石垣上に建ち、一、二階共座敷と次の間からなるが、上下で座敷の向きを逆転させている。二階座敷は杉柾目板を張る竿縁天井に床脇、付書院を備え、高い格式を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012014"},{"id":"00012018","register_sub_id":"101","register_pk":"210959","name":"丸井家住宅塀","kana":"まるいけじゅうたくへい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"大正","pref":"鳥取県","address":"鳥取県倉吉市越中町2148他","lat":35.432058,"lng":133.816487,"geo_status":"db","era":"大正5年頃","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造、瓦葺、延長13m","structure_material":"木造","registered":"2017.10.27(平成29.10.27)","register_no":"31-237","desc":"敷地北面の主屋東方に延びる塀。主屋内庭を区切る塀を南方に延ばす。街路側は腰を焼杉竪板張、上部を赤色の真壁とし、主屋内庭部分には貫格子を入れた菱形窓をあけ、中央に潜戸を設ける。敷地側は灰褐色の土壁刷毛引仕上とする。特徴ある街路景観を作る塀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012018"},{"id":"00012017","register_sub_id":"101","register_pk":"210958","name":"丸井家住宅待合及び塀・袖垣","kana":"まるいけじゅうたくまちあいおよびへい・そでがき","category":"住宅","subcategory":"建築物","type_guess":"塀","type_guess_confidence":"high","period":"大正","pref":"鳥取県","address":"鳥取県倉吉市越中町2149","lat":35.431906,"lng":133.816592,"geo_status":"db","era":"大正5年頃","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"待合 木造平屋建、鋼板葺、建築面積1.9㎡ 塀 木造 瓦葺 延長11m 袖垣 竹製 延長3.8m","structure_material":"待合 木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"31-236","desc":"敷地東辺中央、茶室の東南に位置する。打吹山を借景とした庭園にあって、北から袖垣、腰掛待合、雪隠を配し、鋼板葺の屋根をかける。待合の南北には瓦葺の塀を延ばす。小屋を杉皮野地板、皮付丸垂木に丸太小舞とするなど、庭園景観の一端をなす建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012017"},{"id":"00007669","register_sub_id":"101","register_pk":"108651","name":"美甘家住宅表門","kana":"みかもけじゅうたくおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"鳥取県","address":"鳥取県西伯郡大山町所子字前田170","lat":35.48126755,"lng":133.46870126,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造、瓦葺、間口3.0m","structure_material":"木造","registered":"2009.04.28(平成21.04.28)","register_no":"31 － 0153","desc":"敷地東側の通りから奥に入った位置に建つ。間口３．０ｍの門で、前後に控柱を建てる。柱は方柱で、本・控柱間は貫で固め、竪板を張る。切妻造桟瓦葺で、桟瓦は左桟瓦を用い、棟には熨斗瓦を３枚積み、その上に地元の来待石を載せ、棟端に懸魚風の飾瓦を付ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007669"},{"id":"00007667","register_sub_id":"101","register_pk":"108649","name":"美甘家住宅旧厩","kana":"みかもけじゅうたくきゅううまや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"鳥取県","address":"鳥取県西伯郡大山町所子字前田170","lat":35.48143422,"lng":133.46845855,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、瓦葺、建築面積59㎡","structure_material":"木造平屋建","registered":"2009.04.28(平成21.04.28)","register_no":"31 － 0151","desc":"主屋の北側に倉庫と棟を一直線に並べて建つ。東西棟の切妻造桟瓦葺。桁行７．３ｍ梁間８．０ｍ規模の木造平屋建とする。マヤをコの字型に配し、北寄りは中２階とし、まぐさを貯蔵した。修理で部材の一部が新しくなっているが、往時の佇まいを残している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007667"},{"id":"00007664","register_sub_id":"101","register_pk":"108646","name":"美甘家住宅主屋","kana":"みかもけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"鳥取県","address":"鳥取県西伯郡大山町所子字前田170","lat":35.481258,"lng":133.46849187,"geo_status":"db","era":"江戸後期／明治前期増築","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積216㎡","structure_material":"木造平屋建","registered":"2009.04.28(平成21.04.28)","register_no":"31 － 0148","desc":"敷地中央に東面して建つ。南北棟の切妻造桟瓦葺で、下屋庇を付ける。桁行１９ｍ梁間１２ｍの木造つし２階建。外壁は白漆喰仕上げで、腰に竪板を張る。北に土間、南に２列の居室を配し、前列に主座敷やブツマを設ける。棟に来待石を載せるなど地方的特色を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007664"},{"id":"00007666","register_sub_id":"101","register_pk":"108648","name":"美甘家住宅新蔵","kana":"みかもけじゅうたくしんぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"鳥取県","address":"鳥取県西伯郡大山町所子字前田170","lat":35.48126752,"lng":133.46828485,"geo_status":"db","era":"文久元","year":1861,"year_source":"db","year_min":1861,"year_max":1861,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積31㎡","structure_material":"土蔵造2階建","registered":"2009.04.28(平成21.04.28)","register_no":"31 － 0150","desc":"主屋の西側、裏門の脇に建つ。土蔵造２階建、南北棟の桁行５．９ｍ梁間４．０ｍ。棟に来待石を置く切妻造桟瓦葺で、宝蔵と同様に置屋根を高く上げる。東と北面に瓦葺庇をまわす。白漆喰仕上げで、東面に両開戸を吊る。内部は１、２階とも一室で、竪板壁を張る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007666"},{"id":"00007668","register_sub_id":"101","register_pk":"108650","name":"美甘家住宅倉庫","kana":"みかもけじゅうたくそうこ","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"明治","pref":"鳥取県","address":"鳥取県西伯郡大山町所子字前田170","lat":35.4814167,"lng":133.46833958,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋一部2階建、瓦葺、建築面積111㎡","structure_material":"木造平屋一部2階建","registered":"2009.04.28(平成21.04.28)","register_no":"31 － 0152","desc":"主屋の北側に旧厩の西に建つ。桁行１４ｍ梁間８．８ｍの切妻造桟瓦葺。北半の梁間４．０ｍを２階建とし、南面の軒を深く葺き降ろす。２階建は１階を３室に間仕切り、２階は広い一室とする。南半部は吹放ちの開放的な場とする。屋敷構えを構成する要素のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007668"},{"id":"00007665","register_sub_id":"101","register_pk":"108647","name":"美甘家住宅宝蔵","kana":"みかもけじゅうたくたからぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"鳥取県","address":"鳥取県西伯郡大山町所子字前田170","lat":35.48110423,"lng":133.46847283,"geo_status":"db","era":"明治22","year":1889,"year_source":"db","year_min":1889,"year_max":1889,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積23㎡","structure_material":"土蔵造2階建","registered":"2009.04.28(平成21.04.28)","register_no":"31 － 0149","desc":"敷地南辺の中央東寄りに建つ。東西棟の切妻造桟瓦葺。桁行１３ｍ梁間４．０ｍ規模の木造平屋建。西寄りに門口を設け、両開戸と潜戸を吊り、東側桁行８．８ｍを部屋とする。外壁は黒漆喰仕上げで、腰に竪板を張る。通り沿いの水路や生垣とともに屋敷構えを整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007665"},{"id":"00007670","register_sub_id":"101","register_pk":"108652","name":"美甘家住宅中門及び土塀","kana":"みかもけじゅうたくなかもんおよびどべい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"鳥取県","address":"鳥取県西伯郡大山町所子字前田170","lat":35.48125073,"lng":133.46861756,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"門 木造、瓦葺、間口1.4m、塀 土塀、瓦葺、延長7.8m","structure_material":"門 木造","registered":"2009.04.28(平成21.04.28)","register_no":"31 － 0154","desc":"主屋の主座敷とブツマとの室境筋から南北に建ち、座敷庭と門庭とを仕切る。土塀は総延長７．８ｍで礎石上に方柱を建て、腰板壁で上部漆喰仕上げとする。土塀北寄りに建つ中門は南北棟の切妻造桟瓦葺。間口１．４ｍの腕木門で、竪舞良戸をたてる、軽快な露地門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007670"},{"id":"00004606","register_sub_id":"101","register_pk":"105596","name":"南門脇家住宅旧僧侶用座敷","kana":"みなみかどわきけじゅうたくきゅうそうりょようざしき","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"鳥取県","address":"鳥取県西伯郡大山町所子361","lat":35.48300661,"lng":133.46607308,"geo_status":"db","era":"大正中期","year":1919,"year_source":"estimated","year_min":1916,"year_max":1922,"year_label":"大正中期","structure":"木造平屋建、瓦葺、建築面積17㎡","structure_material":"木造平屋建","registered":"2005.02.09(平成17.02.09)","register_no":"31 － 0087","desc":"敷地南東部にあり，仏事で訪れた僧侶の控室としていた。平屋建，南北棟の切妻造，桟瓦葺で，南妻面は腰を押縁下見板張とし，北妻面には庇を設け，内塀を兼ねた廊下が接続して奥座敷と繋がる。規模は小さいが丁寧なつくりで，大規模な屋敷に相応しい構成要素。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004606"},{"id":"00004607","register_sub_id":"101","register_pk":"105597","name":"南門脇家住宅離れ座敷（旧厩）","kana":"みなみかどわきけじゅうたくはなれざしき（きゅううまや）","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"鳥取県","address":"鳥取県西伯郡大山町所子361","lat":35.48300734,"lng":133.46625241,"geo_status":"db","era":"大正中期","year":1919,"year_source":"estimated","year_min":1916,"year_max":1922,"year_label":"大正中期","structure":"木造平屋建、瓦葺、建築面積25㎡","structure_material":"木造平屋建","registered":"2005.02.09(平成17.02.09)","register_no":"31 － 0088","desc":"当初は厩であったが，後に床を張って離れ座敷とした。真壁造の平屋建，南北棟の切妻造，桟瓦葺で，街路に面した東面と南面は高く押縁下見板張とする。西側には真壁造で，押縁下見板張の塀が取り付く。敷地南東の角地にあって，街路沿いの景観を整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004607"},{"id":"00004608","register_sub_id":"101","register_pk":"105598","name":"南門脇家住宅南納屋","kana":"みなみかどわきけじゅうたくみなみなや","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"鳥取県","address":"鳥取県西伯郡大山町所子361","lat":35.48309149,"lng":133.46624845,"geo_status":"db","era":"大正中期","year":1919,"year_source":"estimated","year_min":1916,"year_max":1922,"year_label":"大正中期","structure":"木造平屋建、瓦葺、建築面積21㎡","structure_material":"木造平屋建","registered":"2005.02.09(平成17.02.09)","register_no":"31 － 0089","desc":"門長屋と離れ座敷の間にある。南北に細長い桁行１４ｍの真壁造，平屋建で，屋根は切妻造，桟瓦葺とする。街路に面した東面は高く押縁下見板張とし，北側上部に縦格子窓を３箇所設ける。敷地正面の東辺にあって，街路沿いの景観を整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004608"},{"id":"00007533","register_sub_id":"101","register_pk":"108515","name":"宮本家住宅主屋","kana":"みやもとけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"鳥取県","address":"鳥取県日野郡日南町菅沢字アブ田井手上ヘ729","lat":35.22832169,"lng":133.3176438,"geo_status":"db","era":"大正2／大正9・昭和2改修","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積274㎡","structure_material":"木造平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"31 － 0140","desc":"石垣を築き構えた屋敷地中央に南面して建つ。木造平屋建、桁行２２ｍ梁間１２ｍで、東面北端に角屋を張り出す。入母屋造桟瓦葺とし、四周に下屋庇をまわす。西寄りに土間、東に床上部を設ける。良質な意匠になるトコや違棚、付書院を東南隅のオモテに構える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007533"},{"id":"00007534","register_sub_id":"101","register_pk":"108516","name":"宮本家住宅土蔵","kana":"みやもとけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"鳥取県","address":"鳥取県日野郡日南町菅沢字アブ田井手上ヘ729","lat":35.22823527,"lng":133.31775801,"geo_status":"db","era":"明治8年／明治37年改修","year":1875,"year_source":"db","year_min":1875,"year_max":1875,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積24㎡","structure_material":"土蔵造2階建","registered":"2009.01.08(平成21.01.08)","register_no":"31 － 0141","desc":"主屋の東に位置する。桁行５．７ｍ梁間４．２ｍ規模の土蔵造２階建。南北棟の切妻造置屋根で、石州赤瓦で葺く。南面を正面とし、１階に庇を掛けて掛子塗の両開戸、２階に庇付の片開戸を備える。外壁は腰板張の白漆喰仕上げで、赤瓦とのコントラストが印象的。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007534"},{"id":"00010881","register_sub_id":"101","register_pk":"201716","name":"矢城家住宅主屋","kana":"やぎけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"鳥取県","address":"鳥取県倉吉市横田693","lat":35.421554,"lng":133.779874,"geo_status":"db","era":"大正2","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"木造2階建、瓦葺、建築面積276㎡","structure_material":"木造2階建","registered":"2015.11.17(平成27.11.17)","register_no":"31 ‐ 0204","desc":"東面して建つ木造二階建、桟瓦葺。一階は南東の庭園に面して座敷を配した六間取で中央に式台を構える。床上三方に縁と吹放しの下屋を廻らす。居室部中央の回り階段やトラス小屋組など近代的特徴を備えた、雄大かつ質の高い住宅で、農村景観に際立つ存在となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010881"},{"id":"00008754","register_sub_id":"101","register_pk":"149475","name":"矢田貝家住宅主屋","kana":"やたがいけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"鳥取県","address":"鳥取県西伯郡伯耆町上細見字樋ノ上486他","lat":35.35729048,"lng":133.43024714,"geo_status":"db","era":"嘉永7年(1854)／昭和前期改修・増築・昭和59年・昭和63年改修","year":1854,"year_source":"converted","year_min":1854,"year_max":1854,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積204㎡","structure_material":"木造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"31 － 0165","desc":"日野川右岸の敷地中央東寄りに東面して建つ。桁行18ｍ梁間12ｍ、木造つし2階建、切妻造桟瓦葺で、南・東面を下屋とする。北半は土間と居室とし、南半の床上部に2列6室を配して表側を接客に用いる。鳥取地方の民家形式をよく伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008754"},{"id":"00008756","register_sub_id":"101","register_pk":"149477","name":"矢田貝家住宅茶室","kana":"やたがいけじゅうたくちゃしつ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"鳥取県","address":"鳥取県西伯郡伯耆町上細見字樋ノ上486他","lat":35.35704519,"lng":133.43020646,"geo_status":"db","era":"昭和前期／昭和63年改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、鉄板葺、建築面積18㎡","structure_material":"木造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"31 － 0167","desc":"離れから露地を隔てて建ち、観楓庵と称する。桁行6.4ｍ梁間3.6ｍ、平屋建、寄棟造鉄板葺で、南・東面に土庇をかける。2畳と4畳半の茶室を、半間幅の水屋を介して東西に並べる。トコ飾りに皮付材を用いるなど、野趣を加味した独特な形式になる茶室。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008756"},{"id":"00008757","register_sub_id":"101","register_pk":"149478","name":"矢田貝家住宅腰掛待合","kana":"やたがいけじゅうたくちゃしつこしかけまちあい","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"鳥取県","address":"鳥取県西伯郡伯耆町上細見字樋ノ上486他","lat":35.35711202,"lng":133.43018806,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、鉄板葺、建築面積6.8㎡","structure_material":"木造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"31 － 0168","desc":"離れと茶室を結ぶ露地に東面して建つ。桁行2.5ｍ梁間1.2ｍ、切妻造銅板葺の本屋に、南・西面では下屋を設けて雪隠とし、東正面には土庇をかける。柱の一部に皮付丸太を使い、桁や垂木も丸太とするなど数寄屋風のつくりで、露地空間に趣を添えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008757"},{"id":"00008761","register_sub_id":"101","register_pk":"149482","name":"矢田貝家住宅中門","kana":"やたがいけじゅうたくちゅうもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"鳥取県","address":"鳥取県西伯郡伯耆町上細見字樋ノ上486他","lat":35.35712608,"lng":133.43024192,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造、鉄板葺、間口1.2m","structure_material":"木造","registered":"2011.07.25(平成23.07.25)","register_no":"31 － 0172","desc":"離れ前面から茶室にのびる塀に開かれた門で、間口1.2ｍ、一間腕木門、切妻造銅板葺である。屋根に軽く起りをもたせ、丸太垂木を使い、扉に網代を張るなど、数寄屋風を加味した意匠になり、露地の入口に相応しい穏やかな印象にまとめている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008761"},{"id":"00008758","register_sub_id":"101","register_pk":"149479","name":"矢田貝家住宅土蔵","kana":"やたがいけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"鳥取県","address":"鳥取県西伯郡伯耆町上細見字樋ノ上486他","lat":35.35722279,"lng":133.43008006,"geo_status":"db","era":"明治中期／昭和63年・平成3年改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積50㎡","structure_material":"土蔵造2階建","registered":"2011.07.25(平成23.07.25)","register_no":"31 － 0169","desc":"主屋背面に北面して建つ。桁行9.7ｍ梁間4.1ｍ、土蔵造2階建、切妻造桟瓦葺で、北面と東面に蔵前を附属する。外部は簓子下見板を腰高に張り、上部は軒まで塗り込めて垂木型を表し、妻面に鶴の鏝絵を飾る。風格のある大型土蔵で、裏庭空間に風情を醸す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008758"},{"id":"00008759","register_sub_id":"101","register_pk":"149480","name":"矢田貝家住宅長屋門","kana":"やたがいけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"鳥取県","address":"鳥取県西伯郡伯耆町上細見字樋ノ上486他","lat":35.3573031,"lng":133.43039852,"geo_status":"db","era":"明治中期／昭和前期移築・平成6年改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積24㎡","structure_material":"木造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"31 － 0170","desc":"主屋玄関の正面、通り沿いに建ち、桁行7.9ｍ梁間3.0ｍ、木造平屋建、切妻造桟瓦葺である。中央に間口2.4ｍの門を開き、北側に潜りを吊る。門の北室は開放的なつくりで腰掛を設け、南室は2畳敷の和室でトコを備える。格式のある表構えを形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008759"},{"id":"00008760","register_sub_id":"101","register_pk":"149481","name":"矢田貝家住宅庭門","kana":"やたがいけじゅうたくにわもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"鳥取県","address":"鳥取県西伯郡伯耆町上細見字樋ノ上486他","lat":35.35727748,"lng":133.4303459,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造、瓦葺、間口2.2m、塀付","structure_material":"木造","registered":"2011.07.25(平成23.07.25)","register_no":"31 － 0171","desc":"主屋と長屋門の間に建ち、間口2.2ｍ、一間腕木門、切妻造桟瓦葺である。柱間に方立一対をたてて欅の板戸を吊り、小脇板も欅板を張る。左右に簓子下見板張で桟瓦葺の塀をのばして主屋と長屋門に接続する。主庭と前庭を画す庭門で、趣ある空間を演出する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008760"},{"id":"00008755","register_sub_id":"101","register_pk":"149476","name":"矢田貝家住宅離れ","kana":"やたがいけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"鳥取県","address":"鳥取県西伯郡伯耆町上細見字樋ノ上486他","lat":35.35717931,"lng":133.4301966,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、瓦葺、建築面積46㎡","structure_material":"木造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"31 － 0166","desc":"主屋南側のブツマに接続し、桁行8.9ｍ梁間5.1ｍ、木造平屋建、入母屋造桟瓦葺である。当地方特有のコドコを備えたオクナンドと、中廊下を介する開放的なつくりの4畳半台目茶室からなり、茶室前面に土庇をかける。瀟洒な佇まいの接客施設である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008755"},{"id":"00009532","register_sub_id":"101","register_pk":"194325","name":"有隣荘石垣","kana":"ゆうりんそういしがき","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"大正","pref":"鳥取県","address":"鳥取県鳥取市国安895-5","lat":35.45635396,"lng":134.21632487,"geo_status":"db","era":"大正12年頃","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"石造、延長45m","structure_material":"石造","registered":"2013.03.29(平成25.03.29)","register_no":"31 － 0182","desc":"土塀の西側に連なる石垣で、主庭の土留擁壁を兼ねる。矩形に加工した大振りの凝灰岩を、正面に勾配を付けて三段布積みとし、積石は縁を江戸切仕上げとする。高さ約一・六メートル延長四五メートルを測り、上部に植栽する。庭園とともに良好な風致を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009532"},{"id":"00009528","register_sub_id":"101","register_pk":"194321","name":"有隣荘三番蔵","kana":"ゆうりんそうさんばんくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"鳥取県","address":"鳥取県鳥取市国安895-5","lat":35.45690192,"lng":134.21640184,"geo_status":"db","era":"大正12年頃","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積36㎡","structure_material":"土蔵造2階建","registered":"2013.03.29(平成25.03.29)","register_no":"31 － 0178","desc":"主屋後方に三棟並ぶ土蔵の中央に東西棟で建つ。土蔵造二階建、桁行六・〇メートル梁間四・一メートル、切妻造桟瓦葺で、南面に二番蔵・四番蔵と一連の下屋を差掛ける。外壁は漆喰塗で背面に竪板を張り、正面上部の海鼠壁に小窓を穿つ。衣装蔵として使用した。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009528"},{"id":"00009530","register_sub_id":"101","register_pk":"194323","name":"有隣荘仕切門及び塀","kana":"ゆうりんそうしきりもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"鳥取県","address":"鳥取県鳥取市国安895-5","lat":35.45650027,"lng":134.21655222,"geo_status":"db","era":"大正12年頃","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"仕切門 木造、瓦葺、間口1.7m 塀 木造、瓦葺、総延長8.1m","structure_material":"仕切門 木造","registered":"2013.03.29(平成25.03.29)","register_no":"31 － 0180","desc":"主屋前面に張出した離れの南側に矩折れにのびる塀と門である。仕切門は間口一・七メートルの南北棟の薬医門で、切妻造桟瓦葺。塀も切妻造桟瓦葺で外壁を漆喰塗とし、腰に簓子下見板を張る。前庭と主庭を仕切る境界装置として、豊かな庭空間を演出している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009530"},{"id":"00009524","register_sub_id":"101","register_pk":"194317","name":"有隣荘主屋","kana":"ゆうりんそうしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"鳥取県","address":"鳥取県鳥取市国安895-5","lat":35.45670585,"lng":134.21655222,"geo_status":"db","era":"大正12年頃／昭和36年改修","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積380㎡","structure_material":"木造平屋建","registered":"2013.03.29(平成25.03.29)","register_no":"31 － 0174","desc":"敷地中央に南面し、木造平屋建、入母屋造桟瓦葺で、周囲に下屋を廻らす。正面中央に入母屋造の玄関、西寄りに離れを、西面には角座敷を張出す。庭に面して座敷を配して縁を廻らし、上質な座敷飾を備える。赤色瓦と腰海鼠壁が特徴的な、大型の近代和風建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009524"},{"id":"00009531","register_sub_id":"101","register_pk":"194324","name":"有隣荘土塀","kana":"ゆうりんそうどべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"大正","pref":"鳥取県","address":"鳥取県鳥取市国安895-5","lat":35.45640479,"lng":134.21679441,"geo_status":"db","era":"大正12年頃","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造、瓦葺、総延長20m","structure_material":"木造","registered":"2013.03.29(平成25.03.29)","register_no":"31 － 0181","desc":"長屋門の左右に折曲がりにのびる土塀。東側延長一四・二メートル西側延長五・四メートル、切妻造桟瓦葺である。布石上に建ち、各柱に腕木を通して軒桁を受ける。外壁は真壁漆喰塗で腰に簓子下見板を張る。長屋門と意匠を揃え、風格ある屋敷構えをつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009531"},{"id":"00009526","register_sub_id":"101","register_pk":"194319","name":"有隣荘長屋門","kana":"ゆうりんそうながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"鳥取県","address":"鳥取県鳥取市国安895-5","lat":35.45642603,"lng":134.21668356,"geo_status":"db","era":"大正12年頃","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積42㎡","structure_material":"木造平屋建","registered":"2013.03.29(平成25.03.29)","register_no":"31 － 0176","desc":"敷地南辺、主屋玄関の正面に構える。木造平屋建、桁行一〇・四メートル梁間四・〇メートル、入母屋造桟瓦葺である。中央間を門口として板戸を吊り、東側に潜戸を開く。両脇間を小部屋とし、外壁は漆喰塗で腰を簓子下見板張とする。旧家の格式を示す長屋門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009526"},{"id":"00009527","register_sub_id":"101","register_pk":"194320","name":"有隣荘二番蔵","kana":"ゆうりんそうにばんくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"鳥取県","address":"鳥取県鳥取市国安895-5","lat":35.45690953,"lng":134.21648559,"geo_status":"db","era":"大正12年頃","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積35㎡","structure_material":"土蔵造2階建","registered":"2013.03.29(平成25.03.29)","register_no":"31 － 0177","desc":"主屋後方に三棟並ぶ土蔵の東端に東西棟で建つ。土蔵造二階建、桁行六・一メートル梁間四・一メートル、切妻造桟瓦葺で、南面に三番蔵・四番蔵と一連の下屋を差掛ける。外壁は漆喰塗で竪板を張り、正面下屋の上を海鼠壁とする。道具蔵として使用した土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009527"},{"id":"00009525","register_sub_id":"101","register_pk":"194318","name":"有隣荘離れ","kana":"ゆうりんそうはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"鳥取県","address":"鳥取県鳥取市国安895-5","lat":35.45669633,"lng":134.21628191,"geo_status":"db","era":"大正12年頃","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積60㎡、渡廊下付","structure_material":"木造平屋建","registered":"2013.03.29(平成25.03.29)","register_no":"31 － 0175","desc":"主屋西側に渡廊下を介して南北棟で建ち、木造平屋建、建築面積六〇平方メートル、入母屋造及び切妻造、桟瓦葺である。栂の良材を用いた「栂の間」を主室とし、床脇に花頭窓を穿つ。南側に次の間と二畳中板付茶室を配し、縁を廻らす。落ち着いた佇まいの離れ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009525"},{"id":"00009529","register_sub_id":"101","register_pk":"194322","name":"有隣荘四番蔵","kana":"ゆうりんそうよんばんくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"鳥取県","address":"鳥取県鳥取市国安895-5","lat":35.45689431,"lng":134.21630666,"geo_status":"db","era":"大正12年頃","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積35㎡","structure_material":"土蔵造2階建","registered":"2013.03.29(平成25.03.29)","register_no":"31 － 0179","desc":"主屋後方に三棟並ぶ土蔵の西端に東西棟で建つ。土蔵造二階建、桁行六・一メートル梁間四・一メートル、切妻造桟瓦葺で、南面に二番蔵・三番蔵と一連の下屋を差掛ける。外壁は漆喰塗で竪板を張り、正面下屋の上を海鼠壁とする。家財蔵として使用した土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009529"},{"id":"00010344","register_sub_id":"101","register_pk":"199117","name":"米原家住宅上門及び塀","kana":"よねはらけじゅうたくかみのもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"鳥取県","address":"鳥取県八頭郡智頭町大字智頭字町ノ内546","lat":35.27013244,"lng":134.22964243,"geo_status":"db","era":"大正前期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"上門 木造、瓦葺、間口4.0m 塀 木造、瓦葺、総延長22m","structure_material":"上門 木造","registered":"2014.12.19(平成26.12.19)","register_no":"31-0200","desc":"主屋の東、智頭往来に面して開く。三間一戸薬医門で控柱を表側に立て、両脇にのびる塀の起点とする。屋根は切妻造桟瓦葺で棟の輪違積に十字紋をあしらう。両開板戸には大振りな八双金物を打ち、天井に幅広の隠岐スギを使う豪壮な門塀で、往来の景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010344"},{"id":"00010345","register_sub_id":"101","register_pk":"199118","name":"米原家住宅下門及び塀","kana":"よねはらけじゅうたくしものもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"鳥取県","address":"鳥取県八頭郡智頭町大字智頭字町ノ内546","lat":35.27000073,"lng":134.22918358,"geo_status":"db","era":"明治39年頃","year":1906,"year_source":"db","year_min":1906,"year_max":1906,"year_label":null,"structure":"下門 木造、瓦葺、間口2.2m 塀 木造、瓦葺、総延長14m","structure_material":"下門 木造","registered":"2014.12.19(平成26.12.19)","register_no":"31-0201","desc":"主屋の南、備前往来に面して開く脇門。切妻造桟瓦葺の一間棟門で、通りより半間奥に建ち、両脇に塀が矩折で取付く。両開板戸に一枚板を張り、乳金物で閂を受ける。棟は青海波で飾り、施釉の鬼瓦には当家の家紋「菱木瓜」を入れる。備前往来側の景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010345"},{"id":"00010342","register_sub_id":"101","register_pk":"199115","name":"米原家住宅主屋","kana":"よねはらけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"鳥取県","address":"鳥取県八頭郡智頭町大字智頭字町ノ内546","lat":35.270136,"lng":134.229417,"geo_status":"db","era":"明治39年頃","year":1906,"year_source":"db","year_min":1906,"year_max":1906,"year_label":null,"structure":"木造2階建、瓦葺、建築面積468㎡","structure_material":"木造2階建","registered":"2014.12.19(平成26.12.19)","register_no":"31-0198","desc":"智頭往来と備前往来の交差する角地に建つ。桁行一二間梁間七間と大規模で、屋根は入母屋造桟瓦葺で四周に下屋を廻らす。外壁は黒漆喰塗、腰はモルタル洗出で破れ目地を切り、出格子を連続させる。良材を駆使した座敷を多数有し、近代豪商の主屋の特徴を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010342"},{"id":"00010343","register_sub_id":"101","register_pk":"199116","name":"米原家住宅土蔵","kana":"よねはらけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"鳥取県","address":"鳥取県八頭郡智頭町大字智頭字町ノ内546他","lat":35.269794,"lng":134.229553,"geo_status":"db","era":"明治中期／昭和30年頃移築","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積69㎡","structure_material":"土蔵造2階建","registered":"2014.12.19(平成26.12.19)","register_no":"31-0199","desc":"敷地南奥に建つ。桁行六間梁間二間半、土蔵造二階建、切妻造桟瓦葺で北面に下屋を付す。一階は二室とし北面に出入口を二箇所設け、二階は一室とする。外壁は漆喰塗で、一階腰壁と下屋上方は海鼠壁とし、目地を山形断面に尖らせる。上質な左官仕事を見せる土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010343"},{"id":"00008166","register_sub_id":"101","register_pk":"132607","name":"石橋家住宅主屋","kana":"いしばしけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"島根県","address":"島根県出雲市平田町字新町834","lat":35.43811241,"lng":132.82127701,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建一部2階建、瓦葺、建築面積262㎡","structure_material":"木造平屋建一部2階建","registered":"2010.04.28(平成22.04.28)","register_no":"32 － 0117","desc":"新町通りに東面する塗屋造の妻入町家で、建築面積２６２㎡、木造平屋建一部２階建、切妻造桟瓦葺である。正面は、左右を下屋造とし、下階に平格子を建て、上階は中央に庇付の格子窓を穿ち、腰を海鼠壁とする。商家が建ち並んだ往時の面影を伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008166"},{"id":"00008167","register_sub_id":"101","register_pk":"132608","name":"石橋家住宅茶室","kana":"いしばしけじゅうたくちゃしつ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"島根県","address":"島根県出雲市平田町字新町834","lat":35.43822235,"lng":132.82130335,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積13㎡","structure_material":"木造平屋建","registered":"2010.04.28(平成22.04.28)","register_no":"32 － 0118","desc":"主屋北東の縁に接続して建つ中板付三畳茶室。 建築面積１３㎡、木造平屋建、寄棟造桟瓦葺で、来待石の棟石を上げる。北面の違棚は背面に大きめの円形下地窓を穿ち、東に踏込床を並べる。東・南面は腰付障子としており、庭に対して開放的な構成とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008167"},{"id":"00008168","register_sub_id":"101","register_pk":"132609","name":"石橋家住宅向座敷","kana":"いしばしけじゅうたくむこうざしき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"島根県","address":"島根県出雲市平田町字新町834","lat":35.43800934,"lng":132.82139153,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積79㎡","structure_material":"木造2階建","registered":"2010.04.28(平成22.04.28)","register_no":"32 － 0119","desc":"主屋の南側、通りに面して建ち、建築面積７９㎡、木造２階建、入母屋造桟瓦葺で、東西面を下屋とする。布石積基礎に建ち、外壁は白漆喰塗籠で、腰を下見板張とし、上下階とも東面に幅の広い格子窓を穿つ。主屋とともに、伝統的な街路景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008168"},{"id":"00003914","register_sub_id":"101","register_pk":"104904","name":"絲原家住宅御成門","kana":"いとはらけじゅうたくおなりもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"島根県","address":"島根県仁多郡奥出雲町大谷856-1","lat":35.17509689,"lng":133.03512608,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、瓦葺、間口2.3m、袖塀付","structure_material":"木造","registered":"2004.02.17(平成16.02.17)","register_no":"32 － 0023","desc":"前座敷と南蔵の間に建つ。藩主御成のための門で，前座敷建設時に西方から曳屋したとされる。棟門形式，桟瓦葺で，両脇に桟瓦葺屋根をかけ腰を簓子下見張とした袖塀が続く。内法高が低く簡素な形式の門だが，前座敷，南蔵と並び屋敷の表構えに欠かせない建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003914"},{"id":"00003917","register_sub_id":"101","register_pk":"104907","name":"絲原家住宅金屋子神社","kana":"いとはらけじゅうたくかながごじんじゃ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"島根県","address":"島根県仁多郡奥出雲町大谷856-21","lat":35.17508795,"lng":133.03480644,"geo_status":"db","era":"明治29","year":1896,"year_source":"db","year_min":1896,"year_max":1896,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積0.9㎡","structure_material":"木造平屋建","registered":"2004.02.17(平成16.02.17)","register_no":"32 － 0026","desc":"宅地北の林の中に祀られた小祠。桁行・梁間各１間，切妻造，妻入で，切石積基壇上に建つ。軒は二軒繁垂木，屋根は銅板葺とする。小規模ながら組物，蟇股，懸魚など彫刻化された細部の派手な造りで，たたら製鉄守護神を祀るものとして鉄師屋敷の象徴的な施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003917"},{"id":"00003912","register_sub_id":"101","register_pk":"104902","name":"絲原家住宅米蔵","kana":"いとはらけじゅうたくこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"島根県","address":"島根県仁多郡奥出雲町大谷856-1","lat":35.17475562,"lng":133.03456863,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積118㎡","structure_material":"土蔵造2階建","registered":"2004.02.17(平成16.02.17)","register_no":"32 － 0021","desc":"主屋の北西に隣接する。桁行５間，梁間３間，土蔵造，２階建で，石州瓦による置屋根とする。戸前となる東面には全面に瓦葺の庇を付ける。外壁は漆喰塗で，腰を海鼠壁とする。１階床を高く張ったたちの高い外観をもち，主屋とともに屋敷北部の構えを形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003912"},{"id":"00003909","register_sub_id":"101","register_pk":"104899","name":"絲原家住宅主屋","kana":"いとはらけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"島根県","address":"島根県仁多郡奥出雲町大谷856-1","lat":35.17458275,"lng":133.0346765,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造2階一部平屋建、瓦葺、建築面積900㎡","structure_material":"木造2階一部平屋建","registered":"2004.02.17(平成16.02.17)","register_no":"32 － 0018","desc":"敷地中央に東面して建つ。入母屋造の主体部の周囲に庇を廻らし，正面に式台玄関を突出する。地元民家の形式を踏襲しつつ間口３０ｍに及ぶ大規模建物で，良材を用いた本格的な書院座敷には近代大工技術の粋が見られる。設計小笠原祥光、棟梁は地元の高田榮蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003909"},{"id":"00003915","register_sub_id":"101","register_pk":"104905","name":"絲原家住宅塀","kana":"いとはらけじゅうたくへい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"島根県","address":"島根県仁多郡奥出雲町大谷856-1","lat":35.17480526,"lng":133.03501839,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造、瓦葺、延長36m","structure_material":"木造","registered":"2004.02.17(平成16.02.17)","register_no":"32 － 0024","desc":"宅地の北東隅部を矩折に仕切る。切石積基壇上に土台を置き，１間毎に柱を立て，各柱上部の短い腕木で出桁を受け，桟瓦葺の屋根をかける。上半を漆喰壁，下半を下見板張に仕上げる。御成門への導入路に沿って長く続き，屋敷の構成要素として欠かせない建造物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003915"},{"id":"00003910","register_sub_id":"101","register_pk":"104900","name":"絲原家住宅前座敷","kana":"いとはらけじゅうたくまえざしき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"島根県","address":"島根県仁多郡奥出雲町大谷856-1","lat":35.17446937,"lng":133.03489996,"geo_status":"db","era":"明治後期／昭和11一部改造","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、鉄板葺一部瓦葺、建築面積150㎡","structure_material":"木造平屋建","registered":"2004.02.17(平成16.02.17)","register_no":"32 － 0019","desc":"主屋東方の庭園に面して建つ。入母屋造の身舎周囲に庇を廻らした形式で，全体をこけら葺とする。規模は大きくないが精緻な造りの本格的な書院建築で，主屋同様座敷３室を一列に並べる。その北に床棚を備え，格天井とする和風を基調とした洋間をとるのも特徴。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003910"},{"id":"00003913","register_sub_id":"101","register_pk":"104903","name":"絲原家住宅待合","kana":"いとはらけじゅうたくまちあい","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"島根県","address":"島根県仁多郡奥出雲町大谷856-1","lat":35.17418708,"lng":133.03480478,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋建、杉皮葺、建築面積3㎡","structure_material":"木造平屋建","registered":"2004.02.17(平成16.02.17)","register_no":"32 － 0022","desc":"南蔵のすぐ西にあり，もと南東方にあった大徳寺真珠庵庭玉軒写しの茶席の待合として建設された。軸部，軒，造作材全てに丸太，曲木を用い，屋根は杉皮葺で，押えや棟に竹を用いた軽快な造りになる。小規模な施設だが，主屋南東の池泉庭園の点景となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003913"},{"id":"00003911","register_sub_id":"101","register_pk":"104901","name":"絲原家住宅南蔵","kana":"いとはらけじゅうたくみなみぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"島根県","address":"島根県仁多郡奥出雲町大谷856-1","lat":35.17424563,"lng":133.03489138,"geo_status":"db","era":"明治9","year":1876,"year_source":"db","year_min":1876,"year_max":1876,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積193㎡","structure_material":"土蔵造2階建","registered":"2004.02.17(平成16.02.17)","register_no":"32 － 0020","desc":"前座敷の南方，東の道沿いに建つ。桁行８間，梁間３間，土蔵造，２階建で，石州瓦による置屋根とする。西面に戸前２口を開くが，屋内は間仕切を設けず１室とする。漆喰塗で，腰部，４隅，また水切瓦上を海鼠壁とするなど，屋敷の表構えに相応しい外観を造る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003911"},{"id":"00003916","register_sub_id":"101","register_pk":"104906","name":"絲原家住宅門柱","kana":"いとはらけじゅうたくもんちゅう","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"島根県","address":"島根県仁多郡奥出雲町大谷856-2","lat":35.17434715,"lng":133.03491906,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"石造、間口3.7m","structure_material":"石造","registered":"2004.02.17(平成16.02.17)","register_no":"32 － 0025","desc":"屋敷の東辺に沿って一直線に続く道の途中に建つ。各高さ約４ｍの花崗岩１石になり，１辺約４５㎝の正方形断面で唐戸面を取り，間口約３．７ｍで立てられる。黒塗門扉があったため黒門とも称される表門で，規模雄大で屋敷導入部を示すにふさわしい格式をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003916"},{"id":"00014410","register_sub_id":"101","register_pk":"511399","name":"新比惠家住宅主屋","kana":"いまひえけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"島根県","address":"島根県益田市小浜町429他","lat":34.67365556,"lng":131.72928333,"geo_status":"db","era":"大正9年頃／昭和５２年改修","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"木造2階建、瓦葺、建築面積253㎡","structure_material":"木造2階建","registered":"2022.10.31(令和4.10.31)","register_no":"32 - 0217","desc":"日本海を背にした漁村旧家の住宅。つし二階建、入母屋造平入桟瓦葺で南面し、北東に棟を延ばし全体でＬ字を呈する。外壁は二階から軒裏まで塗込めて漆喰仕上。内部は6室を配し、南東隅を玄関とし、西列を座敷とする。浜沿いの集落景観をつくる重厚な主屋。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014410"},{"id":"00012805","register_sub_id":"101","register_pk":"367708","name":"上野家住宅奥座敷","kana":"うえのけじゅうたくおくざしき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"島根県","address":"島根県出雲市大社町菱根字山路1130","lat":35.39651278,"lng":132.70166583,"geo_status":"db","era":"明治27年頃","year":1894,"year_source":"db","year_min":1894,"year_max":1894,"year_label":null,"structure":"木造2階建、瓦葺、建築面積38㎡","structure_material":"木造2階建","registered":"2019.03.29(平成31.03.29)","register_no":"32 － 199","desc":"主屋の西側に接続して建つ。切妻造桟瓦葺の二階建で正背面に下屋を付す。内部は上下階とも8畳の座敷と3畳の控間からなる。正面は下屋全面を硝子戸、二階を両端戸袋付の硝子窓とするなど開放的につくる。出雲地方における民家の近代的な展開をよく示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012805"},{"id":"00012804","register_sub_id":"101","register_pk":"367707","name":"上野家住宅主屋","kana":"うえのけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"島根県","address":"島根県出雲市大社町菱根字山路1130","lat":35.39651278,"lng":132.70166583,"geo_status":"db","era":"江戸後期／大正頃・昭和6年頃・同45年改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、茅葺、建築面積145㎡","structure_material":"木造平屋建","registered":"2019.03.29(平成31.03.29)","register_no":"32 － 198","desc":"北山山系南裾の集落の名主宅。主屋は旧大社街道に面する敷地中央に南面して建つ。入母屋造茅葺の平屋建で、四周に桟瓦葺の下屋を廻す。東に土間、西の前後に各3室を配して南西二面に縁を廻し、前列奧に座敷を設ける。出雲地方の伝統形式を伝える近世民家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012804"},{"id":"00012806","register_sub_id":"101","register_pk":"367709","name":"上野家住宅土蔵","kana":"うえのけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"島根県","address":"島根県出雲市大社町菱根字山路1130","lat":35.39651278,"lng":132.70166583,"geo_status":"db","era":"天明8年（1788）／江戸後期移築、明治27年頃増築","year":1788,"year_source":"db","year_min":1788,"year_max":1788,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積27㎡","structure_material":"土蔵造2階建","registered":"2019.03.29(平成31.03.29)","register_no":"32 － 200","desc":"奥座敷の西側に連続して建つ家財蔵。土蔵造二階建、置屋根式の切妻造桟瓦葺で、東端1間の棟を切上げる。外壁は漆喰塗で北面東端に戸口を設ける。内部は上下階とも板敷、小屋は登梁とする。主屋、奥座敷と並び建ち、集落の歴史的景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012806"},{"id":"00004624","register_sub_id":"101","register_pk":"105614","name":"奥野省吾家住宅裏長屋","kana":"おくのしょうごけじゅうたくうらながや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"島根県","address":"島根県安来市伯太町母里188","lat":35.35338521,"lng":133.27394352,"geo_status":"db","era":"明治44","year":1911,"year_source":"db","year_min":1911,"year_max":1911,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積44㎡","structure_material":"木造平屋建","registered":"2005.02.09(平成17.02.09)","register_no":"32 － 0043","desc":"真壁造平屋建，南北棟の切妻造，桟瓦葺で，桁行方向南より戸口を設けた吹き放しの通路，板敷の１室，土間の味噌蔵，吹き放しの土間に間仕切り，壁は中塗り仕上げとする。細長い敷地の東辺に位置し，簡素なつくりであるが，屋敷後方の景観を整える要素。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004624"},{"id":"00004622","register_sub_id":"101","register_pk":"105612","name":"奥野省吾家住宅主屋","kana":"おくのしょうごけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"島根県","address":"島根県安来市伯太町母里188","lat":35.35322835,"lng":133.27356224,"geo_status":"db","era":"明治44","year":1911,"year_source":"db","year_min":1911,"year_max":1911,"year_label":null,"structure":"木造2階建、瓦葺、建築面積158㎡","structure_material":"木造2階建","registered":"2005.02.09(平成17.02.09)","register_no":"32 － 0041","desc":"街道に西面して建つ。真壁造２階建，切妻造，桟瓦葺で，東・西・北の３面に下屋を廻す。１階は南側を通り土間，床上は３室２列に部屋を配し，１階には出格子をつけ，北妻は縦板張とする。たちの高い外観や開口部の多いつくりに，明治末期らしい特徴が窺える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004622"},{"id":"00004623","register_sub_id":"101","register_pk":"105613","name":"奥野省吾家住宅土蔵","kana":"おくのしょうごけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"島根県","address":"島根県安来市伯太町母里188","lat":35.35333049,"lng":133.27370089,"geo_status":"db","era":"明治44","year":1911,"year_source":"db","year_min":1911,"year_max":1911,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積22㎡","structure_material":"土蔵造2階建","registered":"2005.02.09(平成17.02.09)","register_no":"32 － 0042","desc":"主屋の東後方にある。土蔵造２階建，南北棟の切妻造，桟瓦葺で，南妻面に下屋庇を付け，扉口を設ける。屋根は置屋根式で，深い軒をつくる。基礎は切石積，外壁は漆喰塗で，頂部に鉢巻を廻し，妻の棟木木口を円形に象る。全体に丁寧で，堅牢なつくりになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004623"},{"id":"00004625","register_sub_id":"101","register_pk":"105615","name":"奥野省吾家住宅塀","kana":"おくのしょうごけじゅうたくへい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"昭和前","pref":"島根県","address":"島根県安来市伯太町母里188","lat":35.3531008,"lng":133.27364452,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造、延長45m","structure_material":"鉄筋コンクリート造","registered":"2005.02.09(平成17.02.09)","register_no":"32 － 0044","desc":"折曲がり延長４５ｍで，主屋と土蔵の北，敷地北辺西半をコ字型に画する。高さ約２ｍの鉄筋コンクリート造で，土台と柱型をつくりだし，柱頂部を貫で結んだかたちで，柱間はドイツ壁風の仕上げとする。主屋北側の庭を囲み，屋敷構成に欠かせない要素である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004625"},{"id":"00004613","register_sub_id":"101","register_pk":"105603","name":"奥野本家住宅米蔵","kana":"おくのもとけじゅうたくこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"島根県","address":"島根県安来市伯太町母里27","lat":35.35303727,"lng":133.27303696,"geo_status":"db","era":"大正12","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積24㎡","structure_material":"土蔵造2階建","registered":"2005.02.09(平成17.02.09)","register_no":"32 － 0032","desc":"納屋と作業場の間にある。土蔵造２階建，東西棟の切妻造，桟瓦葺で，置屋根式とする。南に扉口を設け，作業場と一連の庇を架け，北面上部には鉄扉付の窓を設ける。切石で築いた換気口付の基礎，隅に面取を施した漆喰壁など，小規模だがつくりは丁寧である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004613"},{"id":"00004614","register_sub_id":"101","register_pk":"105604","name":"奥野本家住宅作業場","kana":"おくのもとけじゅうたくさぎょうば","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"島根県","address":"島根県安来市伯太町母里27","lat":35.35300086,"lng":133.27295145,"geo_status":"db","era":"大正12","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積78㎡","structure_material":"木造平屋建","registered":"2005.02.09(平成17.02.09)","register_no":"32 － 0033","desc":"真壁造平屋建，東西棟の切妻造，桟瓦葺で，屋根と土間庇は米蔵と一連に架け，南面は開放的な扱いとする。内部は西半を板敷で簡素な座敷とし，東半は土間の作業場で，小屋裏を物置とし，南の小壁に窓を設ける。敷地北西隅の景観をかたちづくっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004614"},{"id":"00004610","register_sub_id":"101","register_pk":"105600","name":"奥野本家住宅主屋","kana":"おくのもとけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"島根県","address":"島根県安来市伯太町母里27","lat":35.353039,"lng":133.273346,"geo_status":"db","era":"明治5","year":1872,"year_source":"db","year_min":1872,"year_max":1872,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積365㎡","structure_material":"木造平屋一部2階建","registered":"2005.02.09(平成17.02.09)","register_no":"32 － 0029","desc":"切妻造，平入で，街道に東面する。正面と両側面に下屋庇を廻し，背面に角屋を突出する。一部２階の平屋建であるが，たちが高い外観は豪壮な２階建風で，内部も上質な数寄屋風座敷や豪放な梁組を現した土間など，見所がある。地域の指標となる明治初期の町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004610"},{"id":"00004612","register_sub_id":"101","register_pk":"105602","name":"奥野本家住宅納屋","kana":"おくのもとけじゅうたくなや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"島根県","address":"島根県安来市伯太町母里27","lat":35.35307055,"lng":133.27313134,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造2階建、瓦葺、建築面積47㎡","structure_material":"木造2階建","registered":"2005.02.09(平成17.02.09)","register_no":"32 － 0031","desc":"主屋の北西方にある。真壁造２階建，東西棟の切妻造，桟瓦葺で，南面に扉口を設けて，土蔵と一連の庇を架け，東と北の壁面は縦板張で覆う。内部は東を土間の醤油蔵と味噌蔵，西を板敷の物置に分ける。生活面を支えた施設であるが，規模形式は充実している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004612"},{"id":"00004611","register_sub_id":"101","register_pk":"105601","name":"奥野本家住宅宝庫","kana":"おくのもとけじゅうたくほうこ","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"江戸","pref":"島根県","address":"島根県安来市伯太町母里27","lat":35.35286055,"lng":133.27324852,"geo_status":"db","era":"安政5","year":1858,"year_source":"db","year_min":1858,"year_max":1858,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積46㎡","structure_material":"土蔵造2階建","registered":"2005.02.09(平成17.02.09)","register_no":"32 － 0030","desc":"主屋の南西方にある。土蔵造２階建，東西棟の切妻造，桟瓦葺で，東妻面と北面に庇付の扉口を設け，内部は１・２階と２室に分かれる。外壁漆喰塗で，妻面は棟木木口を円形に象り，置屋根式の屋根が深い軒をつくる。大規模屋敷に相応しい規模形式を備えた施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004611"},{"id":"00008363","register_sub_id":"101","register_pk":"134005","name":"河田家住宅主屋","kana":"かわだけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"島根県","address":"島根県鹿足郡津和野町後田字本町ロ235-1","lat":34.46917831,"lng":131.77476773,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造2階建、瓦葺、建築面積170㎡","structure_material":"木造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"32 － 0155","desc":"通りに東面する間口１１ｍの町家。切妻造桟瓦葺で、正面に鉄板葺庇を付ける。前寄り南半を店舗、その奥を通り土間、北寄りに居室等を配し、背面に便所や台所などを付設する。１階正面は店舗部分に引戸をたて、床上部は鉄格子窓とする。近代商家の面影を残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008363"},{"id":"00012234","register_sub_id":"101","register_pk":"353034","name":"旧美濃地家住宅米蔵","kana":"きゅうみのじけじゅうたくこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"島根県","address":"島根県益田市匹見町道川イ50","lat":34.643964,"lng":132.091029,"geo_status":"db","era":"江戸後期／平成17年改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造2階建、瓦葺、建築面積73㎡","structure_material":"土蔵造2階建","registered":"2018.03.27(平成30.03.27)","register_no":"32-189","desc":"敷地北東隅に主屋と庭を挟んで建つ。桁行六間、梁間三間で白漆喰を軒まで塗込め、腰は下見板を張る。妻には鳳凰と家紋の鏝絵を飾り、道路に面した二階の虫籠窓は輪郭を青色に飾る。小屋は二重梁で受けた棟木に登り梁を架ける。屋敷の表構えに風格を添える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012234"},{"id":"00012233","register_sub_id":"101","register_pk":"353033","name":"旧美濃地家住宅主屋","kana":"きゅうみのじけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"島根県","address":"島根県益田市匹見町道川イ50","lat":34.643735,"lng":132.090661,"geo_status":"db","era":"江戸後期／安政2年(1855)・昭和前期・平成17年改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋一部二階建、茅葺、建築面積333㎡","structure_material":"木造平屋一部二階建","registered":"2018.03.27(平成30.03.27)","register_no":"32-188","desc":"匹見川上流の山間地に東面し、豪雪に備えた急勾配の入母屋造茅葺屋根とする。平面は左土間で、床上部は前後二列に七室を配し、前後列境を土壁で明確に仕切る。式台玄関や上の間を設け高い格式をみせ、後列の座敷にも長押を廻し旧割元庄屋の繁栄を今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012233"},{"id":"00008330","register_sub_id":"101","register_pk":"133972","name":"財間家住宅上の蔵","kana":"ざいまけじゅうたくかみのくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"島根県","address":"島根県鹿足郡津和野町後田字本町ハ38他","lat":34.46769912,"lng":131.77448005,"geo_status":"db","era":"明治後期／昭和前期改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積35㎡","structure_material":"土蔵造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"32 － 0122","desc":"敷地東南隅に位置する。南北棟の切妻造で、西面に瓦葺庇を付ける。石積基礎上に建つ土蔵造２階建で、漆喰仕上げ、南面は高くモルタル洗出し仕上げとし、上部に窓を開ける。内部は中塗仕上げで、板床を張る。西面には掛子塗の両開戸を吊る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008330"},{"id":"00008331","register_sub_id":"101","register_pk":"133973","name":"財間家住宅下の蔵","kana":"ざいまけじゅうたくしものくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"島根県","address":"島根県鹿足郡津和野町後田字本町ハ38他","lat":34.4677874,"lng":131.77454008,"geo_status":"db","era":"明治後期／昭和前期改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積35㎡","structure_material":"土蔵造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"32 － 0123","desc":"上の蔵の北に位置し、その間にヒアイと称し、漬物壺などを置く部屋を設ける。桁行９．６ｍ梁間３．７ｍ、南北棟の切妻造桟瓦葺とする。石積基礎上に建つ土蔵造２階建で、１階内部は南北に二室とし、北に米を納める。上の蔵と一連で敷地東辺の景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008331"},{"id":"00008328","register_sub_id":"101","register_pk":"133970","name":"財間家住宅主屋","kana":"ざいまけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"島根県","address":"島根県鹿足郡津和野町後田字本町ハ38他","lat":34.46786333,"lng":131.7742046,"geo_status":"db","era":"明治後期／昭和前期・昭和中期改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積408㎡","structure_material":"木造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"32 － 0120","desc":"通りに西面する町家。間口１５ｍの木造２階建、北側面に座敷、背面に台所や浴室、便所などを付設する。切妻造桟瓦葺で、正面に下屋を付ける。正面２階は両端を大壁とし、その間に広く格子を構え、１階に平格子や出格子を設ける。津和野の代表的な町家建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008328"},{"id":"00008329","register_sub_id":"101","register_pk":"133971","name":"財間家住宅漬物倉及び木小屋","kana":"ざいまけじゅうたくつけものぐらおよびきごやくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"明治","pref":"島根県","address":"島根県鹿足郡津和野町後田字本町ハ38他","lat":34.46772031,"lng":131.77435292,"geo_status":"db","era":"明治後期／昭和前期改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積35㎡","structure_material":"木造平屋建","registered":"2010.09.10(平成22.09.10)","register_no":"32 － 0121","desc":"主屋背後に接続する台所棟から東西に延びる桁行１２ｍ梁間２．９ｍの木造平屋建。切妻造桟瓦葺。東西三室に分け、西端を土間で井戸を置き、中央を漬物倉、東側を木小屋とする。敷地側は真壁。通り側を大壁とし、主屋から連続して、街路景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008329"},{"id":"00008332","register_sub_id":"101","register_pk":"133974","name":"財間家住宅部屋の蔵","kana":"ざいまけじゅうたくへやのくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"島根県","address":"島根県鹿足郡津和野町後田字本町ハ38他","lat":34.46802224,"lng":131.7742099,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積23㎡","structure_material":"土蔵造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"32 － 0124","desc":"主屋北側に庭を挟んだ位置に南北棟で建つ。桁行５．９ｍ梁間３．９ｍの土蔵造２階建。切妻造桟瓦葺。石積基礎上、漆喰仕上げとし、腰を海鼠壁とする。東面に出入口を設け、掛子塗の両開戸をたて、通り側の上部に窓を開け、銅製の開戸を吊る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008332"},{"id":"00008333","register_sub_id":"101","register_pk":"133975","name":"財間家住宅本門","kana":"ざいまけじゅうたくほんもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"島根県","address":"島根県鹿足郡津和野町後田字本町ハ38他","lat":34.46797986,"lng":131.77416752,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造、瓦葺、間口1.7m、左右袖塀付","structure_material":"木造","registered":"2010.09.10(平成22.09.10)","register_no":"32 － 0125","desc":"主屋の北、通りに面して建つ。一間腕木門で、左右に袖塀を付ける。本柱上、楣で固め、前後に腕木を出し、桁を支持する。一軒疎垂木。切妻造で、桟瓦を葺き、棟は輪違とする。建具は両開戸で、通り側は桟唐戸に作る。主屋や部屋の蔵とともに重厚な屋敷構えを見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008333"},{"id":"00008334","register_sub_id":"101","register_pk":"133976","name":"財間家住宅横門","kana":"ざいまけじゅうたくよこもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"島根県","address":"島根県鹿足郡津和野町後田字本町ハ38他","lat":34.467685,"lng":131.77441825,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造、瓦葺、間口1.8m","structure_material":"木造","registered":"2010.09.10(平成22.09.10)","register_no":"32 － 0126","desc":"屋敷地南側の小路に面する門。漬物倉及び木小屋と上の蔵との間に建つ。間口１．８ｍで、本柱間に蹴放や楣を設け、両開の板戸を吊る。軒は一軒疎垂木。屋根は両下造で、桟瓦を葺き、棟は熨斗積とする。簡易な通用門で、小路沿いの屋敷構えの一端を担う。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008334"},{"id":"00011801","register_sub_id":"101","register_pk":"210817","name":"島田家住宅酒蔵","kana":"しまだけじゅうたくさかぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"島根県","address":"島根県益田市乙吉町イ455-2","lat":34.681821,"lng":131.847835,"geo_status":"db","era":"江戸後期／明治期増築","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造2階建、瓦葺、建築面積298㎡","structure_material":"土蔵造2階建","registered":"2017.06.28(平成29.06.28)","register_no":"32-0186","desc":"敷地西寄りに建つ二階建土蔵。当初の東半七間と明治期の増築と思われる西半の八間半からなり、その西に短い平屋部分が延びる。南面街路側は石垣上に建ち、主体部は軒まで塗込め、屋根は石州瓦の桟瓦葺とする。白漆喰塗の外壁が特徴ある街路景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011801"},{"id":"00011800","register_sub_id":"101","register_pk":"210816","name":"島田家住宅主屋","kana":"しまだけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"島根県","address":"島根県益田市乙吉町イ454","lat":34.682202,"lng":131.848101,"geo_status":"db","era":"明治21年／昭和41年・同50年頃改修","year":1888,"year_source":"db","year_min":1888,"year_max":1888,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、265㎡","structure_material":"木造平屋一部2階建","registered":"2017.06.28(平成29.06.28)","register_no":"32-0187","desc":"益田市中心部の小高い丘の南麓に建つ。主屋は桁行九間半、梁間六間の規模で、切妻造桟瓦葺。西半のみ二階を設ける。左手に土間を取り、床上部は三列八間取。背面東寄りには便所等を突出させる。赤瓦の大屋根が印象的な景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011800"},{"id":"00003691","register_sub_id":"101","register_pk":"104681","name":"角家住宅主屋","kana":"すみけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"島根県","address":"島根県安来市西荒島町字下日白2172","lat":35.42993196,"lng":133.19418458,"geo_status":"db","era":"明治39","year":1906,"year_source":"db","year_min":1906,"year_max":1906,"year_label":null,"structure":"木造2階建、瓦葺、建築面積237㎡","structure_material":"木造2階建","registered":"2003.12.01(平成15.12.01)","register_no":"32 － 0014","desc":"中海南岸から程近い敷地のほぼ中央に建つ。３列９室の床上部の北側に土間を設ける平面で，西よりに３室の２階を設ける。屋根は入母屋造，桟瓦葺で，４方に瓦葺の庇を巡らし，庇上や妻壁下部を海鼠壁とする。豪壮な外観が特徴で，大規模民家建築の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003691"},{"id":"00003693","register_sub_id":"101","register_pk":"104683","name":"角家住宅離れ客間","kana":"すみけじゅうたくはなれきゃくま","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"島根県","address":"島根県安来市西荒島町字下日白2172","lat":35.42987581,"lng":133.19396819,"geo_status":"db","era":"明治39頃","year":1906,"year_source":"db","year_min":1906,"year_max":1906,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積54㎡","structure_material":"木造平屋建","registered":"2003.12.01(平成15.12.01)","register_no":"32 － 0016","desc":"主屋南西隅に渡廊下を介して接続する。内部には水屋，茶室，客間を配し，北側と東側に縁を巡らし，さらに北側に独立した玄関を設けている。屋根は切妻造，桟瓦葺で，茶室・客間部分を一段切り上げる。茶室と客間を複合させた離れの好事例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003693"},{"id":"00003692","register_sub_id":"101","register_pk":"104682","name":"角家住宅門長屋","kana":"すみけじゅうたくもんながや","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"島根県","address":"島根県安来市西荒島町字下日白2172","lat":35.42987966,"lng":133.19435731,"geo_status":"db","era":"明治39頃","year":1906,"year_source":"db","year_min":1906,"year_max":1906,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積36㎡","structure_material":"木造平屋建","registered":"2003.12.01(平成15.12.01)","register_no":"32 － 0015","desc":"敷地の東側北寄りに建つ。入母屋造，桟瓦葺の門長屋で，中央やや北寄りに両開の門を設け，その北側を板敷の物置，南側を床を備える居室としている。壁面上部は漆喰塗，腰部は板張りで，主屋とは異なり赤瓦を用いない。明治後期の農村景観を伝える建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003692"},{"id":"00003694","register_sub_id":"101","register_pk":"104684","name":"角家住宅煉瓦造煙突","kana":"すみけじゅうたくれんがぞうえんとつ","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"島根県","address":"島根県安来市西荒島町字下日白2172","lat":35.43006508,"lng":133.19411092,"geo_status":"db","era":"明治39頃","year":1906,"year_source":"db","year_min":1906,"year_max":1906,"year_label":null,"structure":"煉瓦造、高さ6m","structure_material":"煉瓦造","registered":"2003.12.01(平成15.12.01)","register_no":"32 － 0017","desc":"主屋の西寄りに建つ。当初は煙突に接し台所が設けられていたが，現在では失われている。正方形の断面を持つ煉瓦造煙突で，上部に向かって径を細くする形で，頂部に若干のアクセントを付ける。台所の近代化を物語る遺構で、往時の屋敷構えの一端を今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003694"},{"id":"00012801","register_sub_id":"101","register_pk":"367704","name":"常松家住宅表門","kana":"つねまつけじゅうたくおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"島根県","address":"島根県出雲市斐川町求院字堀川333","lat":35.36872222,"lng":132.7538025,"geo_status":"db","era":"明治7年頃／昭和61年改修","year":1874,"year_source":"db","year_min":1874,"year_max":1874,"year_label":null,"structure":"木造、瓦葺、間口3.5m","structure_material":"木造","registered":"2019.03.29(平成31.03.29)","register_no":"32 － 195","desc":"主屋玄関の正面に位置し、敷地南面の東寄りに建つ。間口3・5メートル、奥行1・8メートル、切妻造桟瓦葺で、間口いっぱいを門口とする。すべて杉の良材を用いる。門口回り等に改変があるが、軸組は当初材をよく残し、旧家の格式ある表構えを形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012801"},{"id":"00012797","register_sub_id":"101","register_pk":"367700","name":"常松家住宅主屋","kana":"つねまつけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"島根県","address":"島根県出雲市斐川町求院字堀川333","lat":35.36872222,"lng":132.7538025,"geo_status":"db","era":"明治7年頃／大正頃・昭和59年改修","year":1874,"year_source":"db","year_min":1874,"year_max":1874,"year_label":null,"structure":"木造平屋建、茅葺、建築面積252㎡","structure_material":"木造平屋建","registered":"2019.03.29(平成31.03.29)","register_no":"32 － 191","desc":"斐伊川東岸の集落の地主宅。主屋は敷地中央に南面して建つ。寄棟造茅葺の平屋建で四周に桟瓦葺の下屋を廻し、東側南端と西側北端に角屋を出す。東に土間、西の前後に各3室を配して中廊下を通し、前列奧を座敷とする。出雲平野の伝統的な民家形式をよく示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012797"},{"id":"00012800","register_sub_id":"101","register_pk":"367703","name":"常松家住宅中門","kana":"つねまつけじゅうたくなかもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"島根県","address":"島根県出雲市斐川町求院字堀川333","lat":35.36872222,"lng":132.7538025,"geo_status":"db","era":"明治7年頃／昭和61年改修","year":1874,"year_source":"db","year_min":1874,"year_max":1874,"year_label":null,"structure":"木造、瓦葺、間口1.7m","structure_material":"木造","registered":"2019.03.29(平成31.03.29)","register_no":"32 － 194","desc":"主屋正面中央から南に延びる塀に設けた薬医門。間口1・7メートル、切妻造桟瓦葺で両端に大ぶりの鬼瓦を載せる。用材はすべて欅を用い、妻を蕪懸魚や桁隠等で装飾する。良材を用いた丁寧なつくりの主屋前庭を画する庭門で、旧家の表構えを格調高く整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012800"},{"id":"00012798","register_sub_id":"101","register_pk":"367701","name":"常松家住宅離れ","kana":"つねまつけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"島根県","address":"島根県出雲市斐川町求院字堀川333","lat":35.36872222,"lng":132.7538025,"geo_status":"db","era":"明治前期／大正頃・昭和30年代改修","year":1868,"year_source":"db","year_min":1868,"year_max":1868,"year_label":null,"structure":"木造2階建、瓦葺、建築面積109㎡","structure_material":"木造2階建","registered":"2019.03.29(平成31.03.29)","register_no":"32 － 192","desc":"主屋東面に接続して建つ。南北棟の南面入母屋造、北面切妻造の桟瓦葺、二階建で四周に下屋を廻す。北端を米蔵とし、南に17畳半の広間と10畳の座敷を並べて東面に廊下を通す。二階は物置とする。主屋とＬ字形に並び建ち、屋敷構えの中核を構成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012798"},{"id":"00012799","register_sub_id":"101","register_pk":"367702","name":"常松家住宅本蔵","kana":"つねまつけじゅうたくほんぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"島根県","address":"島根県出雲市斐川町求院字堀川333","lat":35.36872222,"lng":132.7538025,"geo_status":"db","era":"明治7年頃／平成10年頃改修","year":1874,"year_source":"db","year_min":1874,"year_max":1874,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積29㎡","structure_material":"土蔵造2階建","registered":"2019.03.29(平成31.03.29)","register_no":"32 － 193","desc":"主屋背面に南面して建つ道具蔵。土蔵造二階建、置屋根式の切妻造桟瓦葺で南面に戸口を設ける。外壁は漆喰塗で妻を鏝絵で飾る。内部は上下階とも板敷とする。柱を半間毎に立て、小屋に大梁を用いるなど堅牢につくる。旧家の伝統的な屋敷構えを形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012799"},{"id":"00014933","register_sub_id":"101","register_pk":"519193","name":"中原家住宅主屋","kana":"なかはらけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"島根県","address":"島根県邑智郡美郷町潮村132","lat":35.02032778,"lng":132.63364167,"geo_status":"db","era":"文化6年(1809)／昭和15年頃増築","year":1809,"year_source":"db","year_min":1809,"year_max":1809,"year_label":null,"structure":"木造2階建、瓦葺、建築面積315㎡","structure_material":"木造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"32 - 0218","desc":"江の川東岸の集落にある旧家の主屋。南北棟の石州瓦葺で北を切妻造、南を入母屋造とする。西面に式台と庇付玄関を構え、南東に２階建の角屋を延ばす。北を土間とし上部に太い梁組を現し、南の床上は南西に床を構えた座敷を配す。大規模で旧家の風格を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014933"},{"id":"00014934","register_sub_id":"101","register_pk":"519194","name":"中原家住宅新座敷","kana":"なかはらけじゅうたくしんざしき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"島根県","address":"島根県邑智郡美郷町潮村132","lat":35.02025,"lng":132.63366667,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積74㎡","structure_material":"木造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"32 - 0219","desc":"主屋南東に位置する賓客用の座敷棟。二階建入母屋造桟瓦葺の東西棟とし、北東に平屋建切妻造桟瓦葺南北棟の角座敷を池に張出し、全体に矩折れの平面とする。各階に床構え付き座敷を二室ずつ配し、二階南西室は、床脇に円形の下地窓を開けた瀟洒なつくり。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014934"},{"id":"00014935","register_sub_id":"101","register_pk":"519195","name":"中原家住宅道具蔵","kana":"なかはらけじゅうたくどうぐぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"島根県","address":"島根県邑智郡美郷町潮村132","lat":35.02023889,"lng":132.63362778,"geo_status":"db","era":"寛政5年(1793)","year":1793,"year_source":"db","year_min":1793,"year_max":1793,"year_label":null,"structure":"木造2階建、瓦葺、建築面積130㎡","structure_material":"木造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"32 - 0220","desc":"主屋の南に建つ家財蔵。二階建切妻造平入桟瓦葺の南北棟で、西面に戸口を二箇所開け、南半に下屋を付して蔵前とする。内部１階は西寄りを一室、東寄りを南北２室、二階は１室として中央に独立柱を立てる。桁行長大な土蔵で重厚な外観が歴史的景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014935"},{"id":"00014936","register_sub_id":"101","register_pk":"519196","name":"中原家住宅門及び塀","kana":"なかはらけじゅうたくもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"島根県","address":"島根県邑智郡美郷町潮村132","lat":35.02018056,"lng":132.63358611,"geo_status":"db","era":"文化5年(1808)／大正後期改修","year":1808,"year_source":"db","year_min":1808,"year_max":1808,"year_label":null,"structure":"門 木造、瓦葺、間口1.4m 塀 木造、瓦葺、総延長12m","structure_material":"門 木造","registered":"2024.03.06(令和6.03.06)","register_no":"32 - 0221","desc":"主屋と道具蔵の間に建つ門は一間一戸の腕木門で、屋根は桟瓦葺とする。門の南北に延びる塀は桟瓦葺屋根とし、柱を半間毎に立て、外壁は漆喰仕上、腰はモルタル塗で木瓜形に仕上げる。門口に吊る板戸を外開きとした珍しい門で、旧家の風格ある屋敷構を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014936"},{"id":"00007552","register_sub_id":"101","register_pk":"108534","name":"中村家住宅石垣","kana":"なかむらけじゅうたくいしがき","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"江戸","pref":"島根県","address":"島根県江津市桜江町大貫378-1","lat":34.9523558,"lng":132.40152778,"geo_status":"db","era":"江戸前期／江戸末期改修","year":1638,"year_source":"estimated","year_min":1615,"year_max":1661,"year_label":"江戸前期","structure":"石積、延長125m","structure_material":"石積","registered":"2009.01.08(平成21.01.08)","register_no":"32 － 0102","desc":"屋敷地は東から北にかけて山に囲まれ、西面から南面にかけて石垣を築き、西面に城戸道と称する通路を設ける。石垣は乱積で延長１２５ｍに及び、高さは２～３ｍで、南ほど高くなる。石は地元産の流紋岩が多くを占める。庄屋の堂々たる屋敷構えを伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007552"},{"id":"00007550","register_sub_id":"101","register_pk":"108532","name":"中村家住宅旧郷蔵","kana":"なかむらけじゅうたくきゅうごうぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"島根県","address":"島根県江津市桜江町大貫378-1","lat":34.95225549,"lng":132.40166277,"geo_status":"db","era":"弘化4／昭和中期改修","year":1847,"year_source":"db","year_min":1847,"year_max":1847,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積27㎡","structure_material":"土蔵造2階建","registered":"2009.01.08(平成21.01.08)","register_no":"32 － 0100","desc":"屋敷地の東南隅に位置する。桁行６．９ｍ梁間３．９ｍ規模の土蔵造２階建。東西棟の切妻造で、北面に庇を設け、石州赤瓦で葺く。飢饉などに備えるために籾などを貯蔵する旧大貫村の郷蔵で、地域の歴史を伝える遺構である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007550"},{"id":"00007549","register_sub_id":"101","register_pk":"108531","name":"中村家住宅米雑蔵","kana":"なかむらけじゅうたくこめざつぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"島根県","address":"島根県江津市桜江町大貫378-1","lat":34.95238384,"lng":132.40162946,"geo_status":"db","era":"江戸後期／昭和前期改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造2階建、瓦葺、建築面積72㎡","structure_material":"土蔵造2階建","registered":"2009.01.08(平成21.01.08)","register_no":"32 － 0099","desc":"主屋の東南、納戸蔵の南に建つ。桁行９．９ｍ梁間３．９ｍの土蔵造２階建。南北棟の切妻造で、西面に奥行３．０ｍの下屋庇を付ける。石州赤瓦葺。１階は南北２室に間仕切り、北側に米や籾、南側に藁を保管し、下屋で精米などの作業が行われた。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007549"},{"id":"00007546","register_sub_id":"101","register_pk":"108528","name":"中村家住宅主屋","kana":"なかむらけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"島根県","address":"島根県江津市桜江町大貫378-1","lat":34.95268366,"lng":132.40152714,"geo_status":"db","era":"明治15／明治18増築・昭和63改修","year":1882,"year_source":"db","year_min":1882,"year_max":1882,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積260㎡","structure_material":"木造平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"32 － 0096","desc":"敷地の中央に西面して建つ木造つし２階建。切妻造で三方に下屋庇をまわし、南面に木造２階建の離れを付設する。屋根は石州赤瓦葺とし、壁は白漆喰で塗り込め、風格ある外観をつくる。北寄りを土間、南を六間取の床上部とし、座敷飾りを備える座敷などを配する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007546"},{"id":"00007547","register_sub_id":"101","register_pk":"108529","name":"中村家住宅背戸蔵","kana":"なかむらけじゅうたくせどぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"島根県","address":"島根県江津市桜江町大貫378-1","lat":34.95272887,"lng":132.40164373,"geo_status":"db","era":"江戸末期／明治前期改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積34㎡","structure_material":"土蔵造2階建","registered":"2009.01.08(平成21.01.08)","register_no":"32 － 0097","desc":"主屋土間背面の背戸口の向かいに建つ蔵。桁行６．９ｍ梁間４．９ｍの土蔵造２階建。切妻造石州赤瓦葺で、白漆喰仕上げであった。内部は板床で、荒壁仕上げとする。小屋は梁に束を建て地棟を支持する架構で、竹野地を残し、独特の風合いを伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007547"},{"id":"00007548","register_sub_id":"101","register_pk":"108530","name":"中村家住宅納戸蔵","kana":"なかむらけじゅうたくなんどぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"島根県","address":"島根県江津市桜江町大貫378-1","lat":34.95251071,"lng":132.40162708,"geo_status":"db","era":"明治前期／昭和28頃改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積45㎡","structure_material":"土蔵造2階建","registered":"2009.01.08(平成21.01.08)","register_no":"32 － 0098","desc":"主屋の東南に位置する。桁行７．９ｍ梁間５．９ｍ規模の土蔵造２階建で、高い石積基礎上に建つ。石州赤瓦を葺く東西棟の切妻造で、北面に庇を付ける。１階西半部は部屋に改造され、トコや物入を備え、南面には広く窓を開ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007548"},{"id":"00007551","register_sub_id":"101","register_pk":"108533","name":"中村家住宅農具庫","kana":"なかむらけじゅうたくのうぐこ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"島根県","address":"島根県江津市桜江町大貫378-1","lat":34.95286301,"lng":132.40149859,"geo_status":"db","era":"明治15頃","year":1882,"year_source":"db","year_min":1882,"year_max":1882,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積13㎡","structure_material":"木造平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"32 － 0101","desc":"主屋の北に位置する。南北棟の招屋根で、石州赤瓦で葺く。桁行６．５ｍ梁間２．０ｍの木造平屋建。東面を開放、他を漆喰壁とし、正面から一部側面にかけて腰板を張る。内部は土間で、土壁とする。主屋との間に、塀などを設けて敷地内を画していた。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007551"},{"id":"00007318","register_sub_id":"101","register_pk":"108300","name":"藤井家住宅旧蝋板場","kana":"ふじいけじゅうたくきゅうろういたば","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"島根県","address":"島根県鹿足郡津和野町日原466","lat":34.55013132,"lng":131.83481999,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積74㎡","structure_material":"木造2階建","registered":"2008.07.08(平成20.07.08)","register_no":"32 － 0083","desc":"主屋の西面北寄りに台所土間を介して接続する。東西棟の切妻造桟瓦葺で、南面に庇を付ける。桁行２０ｍ梁間３．６ｍと細長い木造２階建。１階が精蝋の作業所、２階が職人の宿舎として使われた。真壁造で、１階は板壁、２階は漆喰壁。精蝋の歴史を伝える建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007318"},{"id":"00007317","register_sub_id":"101","register_pk":"108299","name":"藤井家住宅主屋","kana":"ふじいけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"島根県","address":"島根県鹿足郡津和野町日原466","lat":34.54999129,"lng":131.83499622,"geo_status":"db","era":"文政8／明治前期・大正期改修","year":1825,"year_source":"db","year_min":1825,"year_max":1825,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積339㎡","structure_material":"木造平屋建","registered":"2008.07.08(平成20.07.08)","register_no":"32 － 0082","desc":"敷地前方に東面して建つ。桁行５間梁間６間の切妻造桟瓦葺に、瓦庇をまわし、奥座敷や座敷など４室を田の字型に配する棟を南側に付設、その西に風呂や温室を設ける。赤瓦屋根に白漆喰壁、虫籠窓、格子、鏝細工など、優れたデザイン感覚が窺える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007317"},{"id":"00007537","register_sub_id":"101","register_pk":"108519","name":"藤田家住宅内蔵","kana":"ふじたけじゅうたくうちぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"島根県","address":"島根県江津市江津町328","lat":35.00834694,"lng":132.22821908,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積47㎡","structure_material":"土蔵造2階建","registered":"2009.01.08(平成21.01.08)","register_no":"32 － 0087","desc":"主屋の東に位置し、座敷と渡廊下で繋がる。２階建土蔵。南北棟で、敷地形状にあわせて南と北で食い違い、内部も２室に分かれる。屋根は切妻造石州赤瓦葺で、外壁は白漆喰仕上げ。小屋は登梁で、その上に横材を渡して、竹野地を流れ方向に張る珍しい技法になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007537"},{"id":"00007542","register_sub_id":"101","register_pk":"108524","name":"藤田家住宅表門","kana":"ふじたけじゅうたくおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"島根県","address":"島根県江津市江津町328","lat":35.00838791,"lng":132.22798106,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、瓦葺、間口1.7m","structure_material":"木造","registered":"2009.01.08(平成21.01.08)","register_no":"32 － 0092","desc":"主屋座敷部の前庭前、本町通りに面して建つ。一間棟門。土台上に方柱を建て、冠木、女梁、男梁を架し、束を立て棟木を支持する。軒は二軒繁垂木で、屋根は切妻造桟瓦葺。雲肘木風の女梁、絵様が彫られる男梁、雲文様の鰭や降懸魚など細部に装飾を施す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007542"},{"id":"00007540","register_sub_id":"101","register_pk":"108522","name":"藤田家住宅北蔵","kana":"ふじたけじゅうたくきたぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"島根県","address":"島根県江津市江津町154","lat":35.008583,"lng":132.22779816,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積69㎡","structure_material":"土蔵造2階建","registered":"2009.01.08(平成21.01.08)","register_no":"32 － 0090","desc":"東蔵の西に位置する。桁行１１ｍ梁間６．４ｍ規模の土蔵造２階建。南北棟の切妻造で石州赤瓦で葺く。１階を２室に間仕切り、２階を広い１室とし、ともに板敷。壁は１階が板壁、２階が土壁。牛梁上に３段に梁を架け、化粧屋根裏を支える架構は見応えがある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007540"},{"id":"00007536","register_sub_id":"101","register_pk":"108518","name":"藤田家住宅主屋","kana":"ふじたけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"島根県","address":"島根県江津市江津町328","lat":35.00842589,"lng":132.22806398,"geo_status":"db","era":"嘉永6","year":1853,"year_source":"db","year_min":1853,"year_max":1853,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積270㎡","structure_material":"木造平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"32 － 0086","desc":"本町通りに西面する。木造つし２階建。切妻造石州赤瓦葺で大棟には直角に煙出を載せ、周囲に下屋庇をまわし、背面に寄棟造の角屋を付ける。壁は白漆喰の大壁造。北に土間を、南には六間取系平面の床上部を配する。豪壮な梁組や洗練された座敷など見応えがある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007536"},{"id":"00007538","register_sub_id":"101","register_pk":"108520","name":"藤田家住宅新蔵及び料理場","kana":"ふじたけじゅうたくしんぐらおよびりょうりば","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"明治","pref":"島根県","address":"島根県江津市江津町328","lat":35.00846189,"lng":132.22828517,"geo_status":"db","era":"明治前期・大正前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造及び木造2階建、瓦葺、建築面積99㎡","structure_material":"土蔵造及び木造2階建","registered":"2009.01.08(平成21.01.08)","register_no":"32 － 0088","desc":"敷地の東北角に位置する。南北棟の新蔵に料理場が直角に付く。切妻造で石州赤瓦葺。新蔵は土蔵造２階建で腰板張の漆喰仕上げ、料理場も同様であるが、南面は真壁造。料理場は１階が調理場、２階を六畳２室とする。内蔵など蔵が連なり重厚な屋敷構えをつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007538"},{"id":"00007539","register_sub_id":"101","register_pk":"108521","name":"藤田家住宅東蔵","kana":"ふじたけじゅうたくひがしぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"島根県","address":"島根県江津市江津町154","lat":35.008572,"lng":132.22788507,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造平屋建、瓦葺、建築面積43㎡","structure_material":"土蔵造平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"32 － 0089","desc":"主屋と本町通りを挟んだ西側の敷地に３棟の土蔵を残す。その敷地の東北隅で本町通りに東面して建つ桁行６．２ｍ梁間５．０ｍ規模の土蔵。切妻造妻入とし、南面に後補の下屋を付ける。外壁は白漆喰仕上げで、屋根に石州赤瓦を葺く。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007539"},{"id":"00007543","register_sub_id":"101","register_pk":"108525","name":"藤田家住宅塀","kana":"ふじたけじゅうたくへい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"江戸","pref":"島根県","address":"島根県江津市江津町328","lat":35.00842654,"lng":132.22796382,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、瓦葺、総延長26m、片引戸付","structure_material":"木造","registered":"2009.01.08(平成21.01.08)","register_no":"32 － 0093","desc":"主屋の座敷前庭、カンジョウバ前庭、ドマ前庭を画する塀で、延長２６ｍに及び、敷地内を仕切る塀には潜りを設ける。土台上に方柱を建て、腕木で軒桁を支え、石州赤瓦を葺く。軒の出や棟高、壁の仕様を場所によって違え、変化に富む屋敷景観を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007543"},{"id":"00007541","register_sub_id":"101","register_pk":"108523","name":"藤田家住宅南蔵","kana":"ふじたけじゅうたくみなみぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"島根県","address":"島根県江津市江津町154","lat":35.00846194,"lng":132.22778405,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積82㎡","structure_material":"土蔵造2階建","registered":"2009.01.08(平成21.01.08)","register_no":"32 － 0091","desc":"北蔵の南に南北棟で建つ。切妻造で、東西に下屋を設け、石州赤瓦で葺く。土蔵造２階建で、内部は各３室に分かれ、１階南２室は畳敷とする。外壁は白漆喰仕上げ。南妻面は、１階に出格子を付け、上部に家紋をあしらい、南面する神社参道を意識した構成になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007541"},{"id":"00008057","register_sub_id":"101","register_pk":"128888","name":"藤田佳宏家住宅表門及び土塀","kana":"ふじたよしひろけじゅうたくおもてもんおよびどべい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"島根県","address":"島根県江津市江津町286他","lat":35.00662591,"lng":132.22667642,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"門 木造、瓦葺、間口2.2m、石橋付 塀 木造、瓦葺、延長17m","structure_material":"門 木造","registered":"2010.01.15(平成22.01.15)","register_no":"32-0107","desc":"表門は敷地前面の東寄りに建ち、一間棟門、切妻造桟瓦葺で、軸部は、独特な形状の肘木と冠木を交差させて腕木を支持する。東西に延びる土塀は敷地前面を流れる本町川の護岸上に建ち、壁体は漆喰塗で、桟瓦を葺き、表門とともに風格ある表構えを構成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008057"},{"id":"00008054","register_sub_id":"101","register_pk":"128885","name":"藤田佳宏家住宅主屋","kana":"ふじたよしひろけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"島根県","address":"島根県江津市江津町286他","lat":35.00653504,"lng":132.22672564,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積132㎡","structure_material":"木造平屋建","registered":"2010.01.15(平成22.01.15)","register_no":"32-0104","desc":"敷地中央に北面して建ち、桁行１３ｍ梁間８．８ｍ、切妻造桟瓦葺で、周囲に下屋、背面に便所棟を付設。外観は正・背面の下部を真壁とし、他は漆喰で塗り込め、土間上部には煙出を突き出す。鍵座敷型の四間取を基本とし、石見地方の伝統的な民家平面を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008054"},{"id":"00008056","register_sub_id":"101","register_pk":"128887","name":"藤田佳宏家住宅納屋","kana":"ふじたよしひろけじゅうたくなや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"島根県","address":"島根県江津市江津町286他","lat":35.00642145,"lng":132.22683671,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積40㎡","structure_material":"土蔵造2階建","registered":"2010.01.15(平成22.01.15)","register_no":"32-0106","desc":"主屋の後方、土蔵の東面に接続する。桁行８．９ｍ梁間３．９ｍ、土蔵造２階建、切妻造桟瓦葺である。土蔵と一連の野面積の石垣上に建ち、東面と北面は腰に竪板を張る。屋根は土蔵と同様に石州赤瓦を葺いており、屋敷地背面の景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008056"},{"id":"00008055","register_sub_id":"101","register_pk":"128886","name":"藤田佳宏家住宅土蔵","kana":"ふじたよしひろじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"島根県","address":"島根県江津市江津町286他","lat":35.00638548,"lng":132.22677171,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積22㎡","structure_material":"土蔵造2階建","registered":"2010.01.15(平成22.01.15)","register_no":"32-0105","desc":"敷地の南西隅、主屋後方に延びる便所棟を介して建つ。桁行４．９ｍ梁間３．９ｍ、土蔵造２階建、切妻造桟瓦葺である。背面側は野面積の石垣上に建ち、１階部分を下屋状に扱う。屋根瓦には赤色の石州瓦を使用しており、歴史的な屋敷構えを形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008055"},{"id":"00006399","register_sub_id":"101","register_pk":"107382","name":"稲積家住宅下の蔵","kana":"ほづみけじゅうたくしたのくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"島根県","address":"島根県邑智郡邑南町井原1189","lat":34.91042963,"lng":132.47483454,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積60㎡","structure_material":"土蔵造2階建","registered":"2007.12.05(平成19.12.05)","register_no":"32 － 0059","desc":"主屋の東方に南北棟で建つ。桁行５間半梁間３間、切妻造石州瓦葺の２階建土蔵で、西面に２ヶ所に戸口を設ける。内部は１階を２室とし、柱は１階２階とも３尺間隔に内転びに立て、小屋は地棟に登梁を架ける。地棟を受ける枕梁に湾曲材を用いる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006399"},{"id":"00006426","register_sub_id":"101","register_pk":"107409","name":"稲積家住宅主屋","kana":"ほづみけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"島根県","address":"島根県邑智郡邑南町井原1189","lat":34.91020596,"lng":132.47451087,"geo_status":"db","era":"江戸末期／明治43改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積256㎡","structure_material":"木造平屋建","registered":"2007.12.05(平成19.12.05)","register_no":"32 － 0057","desc":"井原川の左岸に位置し、南面して東西棟で建つ。桁行１０間梁間５間、切妻造石州瓦葺で、四周に下屋を廻す。東方を土間、西方の床上部を整形六間取とし、西南に座敷を置き、東北には台所を角屋状に突き出す。小屋組は明治の改修で梁を４段に重ね豪壮に造る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006426"},{"id":"00006398","register_sub_id":"101","register_pk":"107381","name":"稲積家住宅背戸の蔵","kana":"ほづみけじゅうたくせどのくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"島根県","address":"島根県邑智郡邑南町井原1189","lat":34.91027425,"lng":132.47442455,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積56㎡","structure_material":"土蔵造2階建","registered":"2007.12.05(平成19.12.05)","register_no":"32 － 0058","desc":"主屋北背面に東西棟で建つ。桁行５間梁間３間、切妻造石州瓦葺の２階建土蔵で、南面と西面に戸口を設ける。石積基礎上に建ち、内部１階は柱を１尺５寸間隔、２階は半間間隔に建て、小屋は地棟に登梁を架ける。屋根は置屋根で、軒まで塗り込める特殊な仕様。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006398"},{"id":"00006400","register_sub_id":"101","register_pk":"107383","name":"稲積家住宅門","kana":"ほづみけじゅうたくもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"島根県","address":"島根県邑智郡邑南町井原1189","lat":34.91017103,"lng":132.47463474,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造、瓦葺、間口2.1m","structure_material":"木造","registered":"2007.12.05(平成19.12.05)","register_no":"32 － 0060","desc":"主屋の土間出入口の南方に位置する。前後に低い控柱を建てる腕木門で、間口は約７尺、棟高９尺、腕木の出２尺の規模で、桟瓦葺の切妻造屋根を架ける。 地元大工の小笠原初市が建設したと伝え、妻飾に懸魚を付けるなど街道からの景観に配慮した造りとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006400"},{"id":"00014086","register_sub_id":"101","register_pk":"508346","name":"三代家住宅主屋","kana":"みしろけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"島根県","address":"島根県松江市美保関町美保関581他","lat":35.56272778,"lng":133.30776667,"geo_status":"db","era":"文久2年（1862）／昭和5年改修","year":1862,"year_source":"db","year_min":1862,"year_max":1862,"year_label":null,"structure":"木造2階建、瓦葺、建築面積140㎡","structure_material":"木造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"32 - 0215","desc":"美保神社東方、廻船問屋が建並ぶ青石畳通に位置する町家。二階建切妻造桟瓦葺。玄関両脇に格子を建て、下屋を通し軒は一、二階とも木鼻付の持送で出桁を受ける。玄関東は洋間、西は表座敷で茶の間を背後に突出。幕末の建物を昭和に改修し、街路景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014086"},{"id":"00011795","register_sub_id":"101","register_pk":"210811","name":"村松家住宅主屋","kana":"むらまつけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"島根県","address":"島根県松江市新雑賀町1519他","lat":35.460635,"lng":133.064423,"geo_status":"db","era":"明治25年／昭和前期頃改修","year":1892,"year_source":"db","year_min":1892,"year_max":1892,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積194㎡","structure_material":"木造平屋一部2階建","registered":"2017.06.28(平成29.06.28)","register_no":"32-0181","desc":"松江城下町南の旧足軽屋敷地に建つ。木造平屋建一部二階建。屋根に左桟瓦、棟に来待石を用い地域性を示し、中廊下型の近代的様相も見せる。一〇畳座敷は一間半の畳床・狆潜・付書院を配し、長押は面皮材を用いる。縁を隔てた中庭と共に上質な空間を構成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011795"},{"id":"00011796","register_sub_id":"101","register_pk":"210812","name":"村松家住宅門及び塀","kana":"むらまつけじゅうたくもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"島根県","address":"島根県松江市新雑賀町1519","lat":35.46055,"lng":133.064446,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"門 木造、瓦葺、間口1.5m、左右袖塀付 塀 コンクリート造、総延長29m","structure_material":"門 木造","registered":"2017.06.28(平成29.06.28)","register_no":"32-0182","desc":"門は玄関正面に建つ間口一・五メートルの腕木門で、両脇に潜戸を付ける。塀はモルタル洗い出しの笠木・柱・土台で枠をつくり、ドイツ壁風に仕上げる。伝統的な門構えと西洋風の近代意匠を併せ持ち、松江城下の戦前の景観を今に伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011796"},{"id":"00008365","register_sub_id":"101","register_pk":"134007","name":"杜塾美術館本館（旧弥重家住宅主屋）","kana":"もりじゅくびじゅつかんほんかん（きゅうやじゅうけじゅうたくしゅおく）","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"島根県","address":"島根県鹿足郡津和野町森村字森イ541-1","lat":34.46440017,"lng":131.77335409,"geo_status":"db","era":"明治元年／平成4年改修","year":1868,"year_source":"db","year_min":1868,"year_max":1868,"year_label":null,"structure":"木造2階建、瓦葺、建築面積423㎡","structure_material":"木造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"32 － 0157","desc":"敷地中央に西面して建つ木造２階建で、南妻に平屋建の角屋を付設する。入母屋造で桟瓦を葺き、四周に庇をまわす。１階は北半部を広い土間とし、豪快な架構を見せる。２階座敷に大トコを構えるほか角屋に良質な座敷を設けるなど、大庄屋の風格を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008365"},{"id":"00008366","register_sub_id":"101","register_pk":"134008","name":"杜塾美術館門（旧弥重家住宅門）","kana":"もりじゅくびじゅつかんもん（きゅうやじゅうけじゅうたくもん）","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"島根県","address":"島根県鹿足郡津和野町森村字森イ541-1","lat":34.4644816,"lng":131.77310672,"geo_status":"db","era":"明治元年／平成4年改修","year":1868,"year_source":"db","year_min":1868,"year_max":1868,"year_label":null,"structure":"木造、瓦葺、間口4.5m","structure_material":"木造","registered":"2010.09.10(平成22.09.10)","register_no":"32 － 0158","desc":"通りに西面して建つ棟門で、三間一戸とし、脇に潜りを穿つ。本柱上に冠木を架し、束をたて棟木を支持し、前後に腕木状に男梁を出し、軒桁をもち出す。一軒疎垂木。切妻造で桟瓦を葺き、棟は青海波とする。規模の大きな表門で、屋敷構えを整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008366"},{"id":"00008066","register_sub_id":"101","register_pk":"128897","name":"山下家住宅石垣","kana":"やましたけじゅうたくいしがき","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"江戸","pref":"島根県","address":"島根県江津市松川町畑田598","lat":35.0105845,"lng":132.30756514,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"石造、延長45m","structure_material":"石造","registered":"2010.01.15(平成22.01.15)","register_no":"32-0116","desc":"斜面地に敷地を造成しており、敷地前面に石垣が築かれる。通りから主屋正面への石段の左右と、通り沿いに延長４５ｍを測り、最も高いところでは３．８ｍに及ぶ。割石を乱積としたもので、隅は算木積風に造る。屋敷地正面に独特の重厚感を与える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008066"},{"id":"00008064","register_sub_id":"101","register_pk":"128895","name":"山下家住宅井戸小屋","kana":"やましたけじゅうたくいどごや","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"島根県","address":"島根県江津市松川町畑田598","lat":35.01098121,"lng":132.30764903,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造、瓦葺、面積4.0㎡","structure_material":"木造","registered":"2010.01.15(平成22.01.15)","register_no":"32-0114","desc":"離れの東南に位置する。南北棟の切妻造で、石州赤瓦葺。桁行１．９ｍ梁間１．９ｍに方柱を建て、直接に桁や梁を架ける。一軒疎垂木を配し、竹小舞野地を見せる。中央に木製の井戸枠を置き、その南側には切石敷の洗い場が残る。生活の一端を示す遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008064"},{"id":"00008059","register_sub_id":"101","register_pk":"128890","name":"山下家住宅主屋","kana":"やましたけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"島根県","address":"島根県江津市松川町畑田598","lat":35.01084664,"lng":132.30740436,"geo_status":"db","era":"明治16","year":1883,"year_source":"db","year_min":1883,"year_max":1883,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積380㎡","structure_material":"木造平屋一部2階建","registered":"2010.01.15(平成22.01.15)","register_no":"32-0109","desc":"敷地の北寄りに位置する。桁行２０ｍ梁間１２ｍ、切妻造石州赤瓦葺の上屋部分を中心に、南正面に下屋庇、西面に切妻屋根などを付設する規模の大きな住宅。木造つし２階建で、西に土間やナカエ、東に九室からなる床上を配する。山間に残る大規模農家建築の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008059"},{"id":"00008061","register_sub_id":"101","register_pk":"128892","name":"山下家住宅背戸蔵","kana":"やましたけじゅうたくせとぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"島根県","address":"島根県江津市松川町畑田598","lat":35.0109148,"lng":132.30731524,"geo_status":"db","era":"明治31","year":1898,"year_source":"db","year_min":1898,"year_max":1898,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積35㎡","structure_material":"土蔵造2階建","registered":"2010.01.15(平成22.01.15)","register_no":"32-0111","desc":"主屋の北側に東西棟で建つ。桁行６．９ｍ梁間５．０ｍの土蔵造２階建。切妻造で石州赤瓦葺とし、白漆喰仕上げ。東面は足下を海鼠壁とし、出入口や窓を開け、家紋を飾る。内部は中塗仕上げ。小屋組は大きく反った梁が直接に棟木を支え、力感溢れる架構を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008061"},{"id":"00008063","register_sub_id":"101","register_pk":"128894","name":"山下家住宅長屋","kana":"やましたけじゅうたくながや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"島根県","address":"島根県江津市松川町畑田598","lat":35.01065266,"lng":132.30743757,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積84㎡","structure_material":"木造2階建","registered":"2010.01.15(平成22.01.15)","register_no":"32-0113","desc":"主屋の西南に位置し、南北棟で建つ木造２階建。桁行１５ｍ梁間５．９ｍで、北側桁行３．９ｍは梁間４．９ｍとする。切妻造で石州赤瓦葺、真壁造。内部は１、２階とも三室に分かれ、１階南室は使用人部屋、中央は馬小屋として使われた。屋敷構えを構成する一要素。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008063"},{"id":"00008060","register_sub_id":"101","register_pk":"128891","name":"山下家住宅離れ","kana":"やましたけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"島根県","address":"島根県江津市松川町畑田598","lat":35.01102315,"lng":132.30748301,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造2階建、瓦葺、建築面積109㎡","structure_material":"木造2階建","registered":"2010.01.15(平成22.01.15)","register_no":"32-0110","desc":"主屋の東に接して建つ木造２階建。東西棟の切妻造で、東面に片流屋根、南・北面に下屋庇を掛け、石州赤瓦で葺く。内部は１、２階とも続き座敷を設け、１階には書斎や書庫、浴室などを付設する。トコや違棚、繊細な付書院などを構える、良質な書院座敷である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008060"},{"id":"00008065","register_sub_id":"101","register_pk":"128896","name":"山下家住宅門及び築地塀","kana":"やましたけじゅうたくもんおよびついじべい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"島根県","address":"島根県江津市松川町畑田598","lat":35.01087985,"lng":132.3075599,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"門 木造、瓦葺、間口2.3m 塀 木造、瓦葺、延長25m","structure_material":"門 木造","registered":"2010.01.15(平成22.01.15)","register_no":"32-0115","desc":"離れの南、主屋の東にある庭園を囲む築地塀で、西面して門を構える。築地塀は白漆喰仕上げ、赤瓦葺で、高さ２．２ｍ、延長２５ｍを測る。門は間口２．３ｍ、切妻造赤瓦葺の腕木門。両開板戸を吊る。軒は一軒疎垂木。白漆喰と赤瓦が庭園景観に彩りを添える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008065"},{"id":"00008062","register_sub_id":"101","register_pk":"128893","name":"山下家住宅門蔵","kana":"やましたけじゅうたくもんぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"島根県","address":"島根県江津市松川町畑田598","lat":35.01090257,"lng":132.30766301,"geo_status":"db","era":"天保12","year":1841,"year_source":"db","year_min":1841,"year_max":1841,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積25㎡","structure_material":"土蔵造2階建","registered":"2010.01.15(平成22.01.15)","register_no":"32-0112","desc":"主屋の東南に南北棟で建つ。桁行６．１ｍ梁間４．１ｍの土蔵造２階建。切妻造で石州赤瓦葺。腰を目板張とする白漆喰仕上げで、軒まで塗り込める。西面に出入口を設け、片引き戸をたて、南面に窓を開ける。敷地東南隅に位置し、敷地景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008062"},{"id":"00004619","register_sub_id":"101","register_pk":"105609","name":"山本家住宅裏長屋","kana":"やまもとけじゅうたくうらながや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"島根県","address":"島根県安来市伯太町母里71","lat":35.35079196,"lng":133.27428017,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積47㎡","structure_material":"木造2階建","registered":"2005.02.09(平成17.02.09)","register_no":"32 － 0038","desc":"東西に長い敷地西辺にある。真壁造２階建，南北棟の切妻造，桟瓦葺で，南側に土間の門口を構え，北側は板敷の１室とし，その東に下屋を設け，妻壁は縦板張とする。２階は南北２室とし，門口脇に洗い場を設ける。簡素であるが，屋敷後方の景観を整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004619"},{"id":"00004620","register_sub_id":"101","register_pk":"105610","name":"山本家住宅釜屋","kana":"やまもとけじゅうたくかまや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"島根県","address":"島根県安来市伯太町母里71","lat":35.35081889,"lng":133.27458345,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積10㎡","structure_material":"木造平屋建","registered":"2005.02.09(平成17.02.09)","register_no":"32 － 0039","desc":"主屋の後方，南寄りにある。真壁造平屋建，東西棟の切妻造，桟瓦葺で，北面中央に引分け戸を設ける。柱は栗材を用い，外壁は中塗り仕上げで，腰を押縁下見板張とする。小規模でつくりも簡素であるが，屋敷背面側の構成要素として欠かせない存在である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004620"},{"id":"00004621","register_sub_id":"101","register_pk":"105611","name":"山本家住宅小蔵","kana":"やまもとけじゅうたくこぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"島根県","address":"島根県安来市伯太町母里71","lat":35.35079427,"lng":133.27454148,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積10㎡","structure_material":"土蔵造2階建","registered":"2005.02.09(平成17.02.09)","register_no":"32 － 0040","desc":"主屋後方，釜屋の西に並び，道具等を収蔵した。土蔵造２階建，東西棟の切妻造，置屋根式の桟瓦葺で，東妻面に戸口を設ける。外壁は丁寧な漆喰塗で，南面と西妻面は縦板で保護し，北は腰を押縁下見板張とする。簡素で小規模な施設ながら，つくりは丁寧である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004621"},{"id":"00004618","register_sub_id":"101","register_pk":"105608","name":"山本家住宅米蔵","kana":"やまもとけじゅうたくこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"島根県","address":"島根県安来市伯太町母里71","lat":35.35085127,"lng":133.27436734,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造2階建、瓦葺、建築面積19㎡、牛小屋付","structure_material":"土蔵造2階建","registered":"2005.02.09(平成17.02.09)","register_no":"32 － 0037","desc":"東西に長い敷地後方にある。米蔵は土蔵造２階建で，西に真壁造平屋建の牛小屋が取り付く。屋根はともに東西棟の切妻造，米蔵は置屋根式で南面の戸口に庇をつけ，桟瓦葺とする。外壁は中塗り仕上げで，簡素なつくりであるが，明治期の屋敷構成を示す付属施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004618"},{"id":"00004617","register_sub_id":"101","register_pk":"105607","name":"山本家住宅新蔵","kana":"やまもとけじゅうたくしんぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"島根県","address":"島根県安来市伯太町母里71","lat":35.35090272,"lng":133.27448127,"geo_status":"db","era":"明治17","year":1884,"year_source":"db","year_min":1884,"year_max":1884,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積19㎡","structure_material":"土蔵造2階建","registered":"2005.02.09(平成17.02.09)","register_no":"32 － 0036","desc":"主屋後方，前蔵西に並び衣類等を収蔵した。土蔵造２階建，東西棟の切妻造，桟瓦葺で，置屋根式とする。南面に観音開扉を設け，下屋庇をつける。基礎は叩き仕上の切石積とし，外壁は頂部に鉢巻を廻して西面を縦板張で覆う。側廻りから軸組まで，堅牢なつくり。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004617"},{"id":"00004616","register_sub_id":"101","register_pk":"105606","name":"山本家住宅前蔵","kana":"やまもとけじゅうたくまえぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"島根県","address":"島根県安来市伯太町母里71","lat":35.35094086,"lng":133.27454155,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造2階建、瓦葺、建築面積23㎡","structure_material":"土蔵造2階建","registered":"2005.02.09(平成17.02.09)","register_no":"32 － 0035","desc":"主屋後方にあり，什器等を収蔵した。土蔵造２階建，東西棟の切妻造，桟瓦葺で，置屋根式とする。南面に扉口と下屋庇を設け，東面上部に小庇付窓を設ける。基礎は換気口付の切石積，東と北の壁面は縦板張とする。側廻りから軸組まで，小規模だがつくりは丁寧。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004616"},{"id":"00002819","register_sub_id":"101","register_pk":"103809","name":"大賀家住宅内蔵","kana":"おおがけじゅうたくうちぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県岡山市北区今保755","lat":34.63530876,"lng":133.87736316,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造平屋建、瓦葺、建築面積55㎡","structure_material":"土蔵造平屋建","registered":"2002.06.25(平成14.06.25)","register_no":"33 － 0062","desc":"離座敷の北側，二階座敷の西側にある。二階座敷とともに屋敷後方の収納施設として整えられた。２階建の土蔵造で，屋根は切妻造・本瓦葺，漆喰塗の外壁は鉢巻から下を縦板で覆う。南面と西面の小窓は鉄格子や厚い片開き漆喰戸など，つくりは厳重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002819"},{"id":"00002822","register_sub_id":"101","register_pk":"103812","name":"大賀家住宅表門","kana":"おおがけじゅうたくおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"岡山県","address":"岡山県岡山市北区今保755","lat":34.63501759,"lng":133.87759867,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造、瓦葺、間口4.1m","structure_material":"木造","registered":"2002.06.25(平成14.06.25)","register_no":"33 － 0065","desc":"主屋の東側，水路に面して建っている。入母屋造・本瓦葺，桁行２間，梁間１間半の規模で，梁間前側半間に戸口を設け，引分の板戸と格子戸を入れる。正面と背面の内法を固める成の高い差物，出桁造を用いた深い軒など，屋敷の正面にふさわしい形態である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002822"},{"id":"00002818","register_sub_id":"101","register_pk":"103808","name":"大賀家住宅雑具物置及び臼場","kana":"おおがけじゅうたくざつぐものおきおよびうすば","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"岡山県","address":"岡山県岡山市北区今保755","lat":34.63499373,"lng":133.87757303,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積20㎡","structure_material":"木造平屋建","registered":"2002.06.25(平成14.06.25)","register_no":"33 － 0061","desc":"表門の南側に連続して建っている。平屋建，切妻造・本瓦葺で，屋敷内側に鉄板葺の庇をつける。平面はＬ字型で，表門側を雑具の物置，南側を臼場とする。梁間１間の小規模な附属施設であるが，外観は重厚で，うまく屋敷正面の角地の景観を整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002818"},{"id":"00002814","register_sub_id":"101","register_pk":"103804","name":"大賀家住宅主屋","kana":"おおがけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"岡山県","address":"岡山県岡山市北区今保755","lat":34.63514966,"lng":133.87750631,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造2階建、瓦葺、建築面積204㎡","structure_material":"木造2階建","registered":"2002.06.25(平成14.06.25)","register_no":"33 － 0057","desc":"岡山市街の西方，笹ケ瀬川と足守川の合流点付近にある。南面して建つ主屋は土間が狭い６間取平面で，床・棚・書院など上質の構えを備える。屋根は煙出付の入母屋造・本瓦葺，南と西に庇を廻し，妻飾を海鼠壁にするなど，豪壮な屋敷景観の核となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002814"},{"id":"00002821","register_sub_id":"101","register_pk":"103811","name":"大賀家住宅漬物納屋及び荷揚納屋","kana":"おおがけじゅうたくつけものなやおよびにあげなや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"江戸","pref":"岡山県","address":"岡山県岡山市北区今保755","lat":34.63535716,"lng":133.87753466,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積48㎡","structure_material":"木造平屋建","registered":"2002.06.25(平成14.06.25)","register_no":"33 － 0064","desc":"屋敷の北側，納屋に連続して建つ。平屋建，本瓦葺で，平面は細長い矩折れになり，漬物納屋部分は真壁造の１室とするが，ほかは水路側を荷揚用の門と壁，屋敷内側を吹放しとする。大量の物資を扱った商家に欠かせない施設で，屋敷後方の景観も構成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002821"},{"id":"00002817","register_sub_id":"101","register_pk":"103807","name":"大賀家住宅納屋","kana":"おおがけじゅうたくなや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"江戸","pref":"岡山県","address":"岡山県岡山市北区今保755","lat":34.63527743,"lng":133.87754011,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積19㎡","structure_material":"木造平屋建","registered":"2002.06.25(平成14.06.25)","register_no":"33 － 0060","desc":"主屋西側の土間部から北に延びた勝手場と連続して建っている。平屋建，切妻造・本瓦葺で，北面と西面に庇をつける。水路に架かるため，斜めに隅切りされた北東隅は，屋根も巧みに処理している。主屋後方にあって，屋敷構えを一体感のあるものにしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002817"},{"id":"00002816","register_sub_id":"101","register_pk":"103806","name":"大賀家住宅二階座敷","kana":"おおがけじゅうたくにかいざしき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"岡山県","address":"岡山県岡山市北区今保755","lat":34.63528633,"lng":133.87748082,"geo_status":"db","era":"江戸後期／明治中期移築","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造2階建、瓦葺、建築面積61㎡","structure_material":"木造2階建","registered":"2002.06.25(平成14.06.25)","register_no":"33 － 0059","desc":"主屋の北側，内蔵の東側に建ち，蔵前を兼ねているが，明治中期頃に他から移築してきた。木造２階建，本瓦葺で，東側が入母屋造，西側が切妻造になる。各階とも６畳間２室の構成で，縁板の桜材や天井の面皮杉の棹縁など用材に凝った丁寧なつくりである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002816"},{"id":"00002815","register_sub_id":"101","register_pk":"103805","name":"大賀家住宅離座敷","kana":"おおがけじゅうたくはなれざしき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"岡山県","address":"岡山県岡山市北区今保755","lat":34.63520475,"lng":133.87736557,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造平屋建、瓦葺、建築面積75㎡","structure_material":"木造平屋建","registered":"2002.06.25(平成14.06.25)","register_no":"33 － 0058","desc":"主屋の西側にあり廊下で接続する。南北棟の入母屋造・本瓦葺，東と南に桟瓦葺の庇を廻し，西南隅に風呂・便所を附属する。南側に庭園を鑑賞するよう配された８畳間の座敷は，数寄屋風の意匠で纏められており，床・棚・書院のつくりも丁寧で質が高い。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002815"},{"id":"00011403","register_sub_id":"101","register_pk":"209240","name":"旧木村家住宅土蔵","kana":"きゅうきむらけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"岡山県","address":"岡山県勝田郡勝央町勝間田字上ノ町635","lat":35.038565,"lng":134.115404,"geo_status":"db","era":"江戸末期／昭和38・平成4改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積34㎡","structure_material":"土蔵造2階建","registered":"2016.11.29(平成28.11.29)","register_no":"33－0275","desc":"出雲往来勝間田宿の旧脇本陣敷地に残る唯一の遺構で、参勤交代の要衝でもあった宿場町の景観を今に伝える。土蔵造二階建、切妻造桟瓦葺で、一・二階とも一室とする。切石積基礎の上で軒まで塗込め、壁の大部分を海鼠壁として特徴ある外観を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011403"},{"id":"00014200","register_sub_id":"101","register_pk":"508830","name":"旧荘家住宅座敷棟","kana":"きゅうしょうけじゅうたくざしきむね","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"岡山県","address":"岡山県真庭市下呰部字町664","lat":34.96443333,"lng":133.62881111,"geo_status":"db","era":"文政8年(1825)／平成26年改修","year":1825,"year_source":"db","year_min":1825,"year_max":1825,"year_label":null,"structure":"木造2階建、瓦葺、建築面積170㎡","structure_material":"木造2階建","registered":"2022.02.17(令和4.02.17)","register_no":"33-0349","desc":"伯雲往来に東面する旧庄屋の座敷棟。二階建、入母屋造平入桟瓦葺で、南東に玄関を突出する。内部は南に土間、北に二列四室を並べ、東庭を臨んで続き座敷とする。二階は背面側に続き座敷を配する。外壁は大壁造漆喰塗で重厚にみせ、街道沿いの景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014200"},{"id":"00012028","register_sub_id":"101","register_pk":"210969","name":"旧永瀬家住宅井戸","kana":"きゅうながせけじゅうたくいど","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"岡山県","address":"岡山県赤磐市松木689-2","lat":34.79368,"lng":134.093817,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"石造、面積1.4㎡、建屋付","structure_material":"石造","registered":"2017.10.27(平成29.10.27)","register_no":"33-281","desc":"主屋南東方に建つ。井戸は荒石を円筒形に組み上げ、上部井桁は石板で正方形に組む。上家は木造桟瓦葺で、柱をやや内転びに立て、北面、東面及び南面東寄りは竪板壁とし、西面と南面西寄りは吹放ちとする。永瀬清子の詩にも描かれた井戸である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012028"},{"id":"00012027","register_sub_id":"101","register_pk":"210968","name":"旧永瀬家住宅主屋","kana":"きゅうながせけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県赤磐市松木691","lat":34.793859,"lng":134.093639,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造2階建、鉄板葺一部瓦葺、建築面積87㎡","structure_material":"木造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"33-280","desc":"木造二階建、入母屋造鉄板葺で、正面左に入口を開き、やや不整形の土間を通す。奥の土間はレンガを四半に敷く。床上部は田字型で、二階もほぼ同様の構成を採る。日本の女性詩人の草分けと言われた永瀬清子の生家であり、地元で広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012027"},{"id":"00012635","register_sub_id":"101","register_pk":"367929","name":"旧中山家住宅米蔵","kana":"きゅうなかやまけじゅうたくこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"岡山県","address":"岡山県倉敷市連島町西之浦字長堂2954-1他","lat":34.555969,"lng":133.710602,"geo_status":"geocoded","era":"大正3年頃","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積69㎡","structure_material":"土蔵造2階建","registered":"2018.11.02(平成30.11.02)","register_no":"33 － 0300","desc":"中蔵の北隣に並び、高い石積基礎上に東西棟で建つ、切妻造本瓦葺、二階建の土蔵。東妻の南寄りに庇付の戸口を設け、石段を築く。平面は中蔵より大きいが、外壁の黒漆喰塗、腰と四隅の海鼠壁や水切瓦など中蔵と共通の外観で、重厚な屋敷構えを形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012635"},{"id":"00012632","register_sub_id":"101","register_pk":"367926","name":"旧中山家住宅主屋","kana":"きゅうなかやまけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"岡山県","address":"岡山県倉敷市連島町西之浦字長堂2954-2他","lat":34.555969,"lng":133.710602,"geo_status":"geocoded","era":"大正3年頃","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積358㎡","structure_material":"木造平屋建","registered":"2018.11.02(平成30.11.02)","register_no":"33 － 0297","desc":"高梁川東岸の丘陵南麓にある実業家宅で、主屋は敷地中央に南面して建つ。入母屋造に深い軒の下屋を廻し、正面に入母屋玄関を出す。西半は中廊下の前後に座敷を配し、15畳の表座敷に大ぶりの座敷飾を備える。良材を用いた上質な造作をもつ豪壮な和風住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012632"},{"id":"00012634","register_sub_id":"101","register_pk":"367928","name":"旧中山家住宅中蔵","kana":"きゅうなかやまけじゅうたくなかぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"岡山県","address":"岡山県倉敷市連島町西之浦字長堂2954-1他","lat":34.555969,"lng":133.710602,"geo_status":"geocoded","era":"大正3年頃","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積60㎡","structure_material":"土蔵造2階建","registered":"2018.11.02(平成30.11.02)","register_no":"33 － 0299","desc":"離れ屋及び内蔵の北側、高い石積基礎上に東西棟で建つ、切妻造本瓦葺、二階建の土蔵。外壁黒漆喰塗で上下階の腰と四隅を海鼠壁とし、瓦の水切を廻す。東妻の北寄りに庇付の戸口を設け、石段を築く。北側に並び建つ米蔵と同じく重厚な屋敷構えを形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012634"},{"id":"00012636","register_sub_id":"101","register_pk":"367930","name":"旧中山家住宅長屋門","kana":"きゅうなかやまけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"岡山県","address":"岡山県倉敷市連島町西之浦字長堂2955他","lat":34.555969,"lng":133.710602,"geo_status":"geocoded","era":"大正4年頃","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積165㎡","structure_material":"木造平屋一部2階建","registered":"2018.11.02(平成30.11.02)","register_no":"33 － 0301","desc":"敷地東辺に建つ、桁行27メートルに及ぶ長大な長屋門。入母屋造本瓦葺で、中央を間口の広い門口とし、木太い柱や差物、幅広の壁板、扉などに上質な欅材を用いる。門口の左右は腰海鼠壁、上部漆喰塗で、出桁造の軒まで塗込める。城門を彷彿させる雄大な表門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012636"},{"id":"00012633","register_sub_id":"101","register_pk":"367927","name":"旧中山家住宅離れ屋及び内蔵","kana":"きゅうなかやまけじゅうたくはなれやおよびうちぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"岡山県","address":"岡山県倉敷市連島町西之浦字長堂2954-2他","lat":34.555969,"lng":133.710602,"geo_status":"geocoded","era":"大正3年頃","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造及び土蔵造2階建、瓦葺、建築面積103㎡","structure_material":"木造及び土蔵造2階建","registered":"2018.11.02(平成30.11.02)","register_no":"33 － 0298","desc":"主屋西面に渡廊下で接続する離れとその北側に連なる土蔵からなる。南北棟の二階建、離れ屋は南面入母屋造桟瓦葺で上下階に庇を廻す。内蔵は土蔵造、切妻造桟瓦葺、黒漆喰塗で、上下階の腰を海鼠壁とする。瀟洒な離れと重厚な土蔵を連結した特色ある附属建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012633"},{"id":"00016726","register_sub_id":"101","register_pk":"579210","name":"旧仁科家住宅主屋","kana":"きゅうにしなけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"岡山県","address":"岡山県浅口郡里庄町大字浜中字東田717","lat":34.498991,"lng":133.53657,"geo_status":"db","era":"江戸後期／明治中期・同後期増築","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建一部2階建、瓦葺、建築面積254㎡","structure_material":"木造平屋建一部2階建","registered":"2026.07.09(令和8.07.09)","register_no":"33 - 0395","desc":"茶臼山北麓に南面して建つ旧庄屋の主屋。入母屋造本瓦葺平入で南面に下屋を付し、北面の東に台所、北西に二階建の居室棟が突出する。南面中央に式台付き玄関を構え、床上は食違いの四間取とし、南西に八畳の床構え付き座敷とする。造作丁寧な上層農家の主屋。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016726"},{"id":"00012026","register_sub_id":"101","register_pk":"210967","name":"旧林家住宅","kana":"きゅうはやしけじゅうたく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"low","period":"大正","pref":"岡山県","address":"岡山県倉敷市祐安字寺谷1451","lat":34.618158,"lng":133.75798,"geo_status":"db","era":"大正12年頃／昭和35年増改築","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造2階建、瓦葺、建築面積154㎡","structure_material":"木造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"33-279","desc":"倉敷の大原家が良質な住宅地として開発した地区に位置する木造二階建の住宅。西村伊作の設計で、彼の「田園小住家」の理想を具現化しようとしたもの。南東角の玄関奥にホールを配し西に中廊下を通して南に洋風のリビング、ダイニングを、北に水廻りを配す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012026"},{"id":"00006412","register_sub_id":"101","register_pk":"107395","name":"旧松井家住宅主屋","kana":"きゅうまついけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"岡山県","address":"岡山県総社市上林1208-2","lat":34.6683043,"lng":133.78722865,"geo_status":"db","era":"江戸末期／昭和47年移築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、茅葺、建築面積60㎡","structure_material":"木造平屋建","registered":"2007.10.02(平成19.10.02)","register_no":"33 － 0161","desc":"岡山市沼の旧山陽道沿いの茶屋として建設。桁行５間、梁間３間の木造平屋建で、寄棟造茅葺の平入とする。表裏に瓦葺の庇をつける。内部は正面向かって右手を土間とし、左手を喰違四間取の居室とし、縁は設けない。簡明な農家建築の形式を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006412"},{"id":"00006411","register_sub_id":"101","register_pk":"107394","name":"旧山手村役場","kana":"きゅうやまてそんやくば","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"low","period":"明治","pref":"岡山県","address":"岡山県総社市上林1214-1","lat":34.66816804,"lng":133.78685932,"geo_status":"db","era":"明治初期／昭和47移築","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造平屋建、茅葺、建築面積169㎡、袖塀・中門付","structure_material":"木造平屋建","registered":"2007.10.02(平成19.10.02)","register_no":"33 － 0162","desc":"元は山手村初代村長の住宅で、明治３５年から村役場として使用。桁行７間半、梁行５間の木造平屋建で、入母屋造茅葺とし、四周に本瓦葺の下屋を設け、座敷前は土縁とする。正面に式台を構え、右手を土間、左手を四間取の居室とする。甍棟に格式を表した建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006411"},{"id":"00001939","register_sub_id":"101","register_pk":"102929","name":"旧柚木家住宅（西爽亭）御成門","kana":"きゅうゆのきけじゅうたく（さいそうてい）おなりもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"岡山県","address":"岡山県倉敷市玉島3-8-25","lat":34.5414659,"lng":133.67144317,"geo_status":"db","era":"天明年間","year":1784,"year_source":"estimated","year_min":1781,"year_max":1788,"year_label":"天明年間","structure":"木造薬医門、瓦葺、間口3.9m","structure_material":"木造薬医門","registered":"2000.10.18(平成12.10.18)","register_no":"33 － 0049","desc":"柚木家は，松山藩から奉行格の待遇を受けていた玉島の大庄屋である。通りに面する御成門は，意匠の凝った鬼瓦を隅棟に載せた本瓦葺の薬医門形式を取る。備中に残る民家の門の中で最大級規模を誇り，海運都市玉島の繁栄を象徴する景観形成に寄与している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001939"},{"id":"00001938","register_sub_id":"101","register_pk":"102928","name":"旧柚木家住宅（西爽亭）主屋","kana":"きゅうゆのきけじゅうたく（さいそうてい）しゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"岡山県","address":"岡山県倉敷市玉島3-8-25","lat":34.54135103,"lng":133.67153445,"geo_status":"db","era":"天明年間","year":1784,"year_source":"estimated","year_min":1781,"year_max":1788,"year_label":"天明年間","structure":"木造平屋建、瓦葺、建築面積106㎡","structure_material":"木造平屋建","registered":"2000.10.18(平成12.10.18)","register_no":"33 － 0048","desc":"江戸時代，海運で栄えた玉島港の南東，山麓に建つ。木造平屋建，本瓦葺。むくりをつけた唐破風様の妻飾を頂く２間幅の式台から，取次の間，数寄屋風の書院，湯殿・便所が順に続く。内部は格式と格調高い意匠でまとめられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001938"},{"id":"00001940","register_sub_id":"101","register_pk":"102930","name":"旧柚木家住宅（西爽亭）茶室","kana":"きゅうゆのきけじゅうたく（さいそうてい）ちゃしつ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"江戸","pref":"岡山県","address":"岡山県倉敷市玉島3-8-25","lat":34.54123852,"lng":133.67158117,"geo_status":"db","era":"天明年間","year":1784,"year_source":"estimated","year_min":1781,"year_max":1788,"year_label":"天明年間","structure":"木造平屋建、銅板葺、建築面積8.9㎡","structure_material":"木造平屋建","registered":"2000.10.18(平成12.10.18)","register_no":"33 － 0050","desc":"屋敷地の南隅に建つ。勾配の緩やかな銅板葺の屋根を架ける。台目畳３畳と中板からなる特異な平面形式を持つ茶室と，庭の傾斜を利用し懸造状に張りだす台目畳２畳の煎茶席よりなり，庭に面する壁面を障子戸で覆い舞台装置的効果を高める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001940"},{"id":"00012025","register_sub_id":"101","register_pk":"210966","name":"旧吉田彦七家住宅","kana":"きゅうよしだひこしちけじゅうたく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"low","period":"昭和前","pref":"岡山県","address":"岡山県倉敷市水島西栄町24-7","lat":34.53685,"lng":133.742462,"geo_status":"db","era":"昭和18年／昭和33年増築、平成29年改修","year":1943,"year_source":"db","year_min":1943,"year_max":1943,"year_label":null,"structure":"木造平屋建、瓦葺一部鋼板葺、建築面積78㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"33-278","desc":"水島市街地に建つ。昭和一八年に操業を開始した三菱重工業水島航空機製作所の工員用社宅として建てられた数少ない遺存例。木造平屋建、桟瓦葺で、寄棟造の四周に下屋をかける構造。昭和戦中期の小規模社宅の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012025"},{"id":"00000089","register_sub_id":"101","register_pk":"101079","name":"楠戸家住宅米蔵","kana":"くすどけじゅうたくこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県倉敷市東町1-20","lat":34.59751989,"lng":133.77570396,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積96㎡","structure_material":"土蔵造2階建","registered":"1996.12.20(平成8.12.20)","register_no":"33 － 0002","desc":"屋敷地の背後に建つ米蔵は，２階建，本瓦葺，大壁造の長大な建物で，腰廻りや水切りの小庇等は海鼠壁とする重厚な意匠からなる。基礎は一段高い切石積みとなる。東妻側は背後への通路を兼ねる。他の蔵とも，明治期の屋敷地の構成を知る上で重要な建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000089"},{"id":"00000090","register_sub_id":"101","register_pk":"101080","name":"楠戸家住宅炭倉","kana":"くすどけじゅうたくすみぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県倉敷市東町1-20","lat":34.59746451,"lng":133.7756498,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積19㎡","structure_material":"土蔵造2階建","registered":"1996.12.20(平成8.12.20)","register_no":"33 － 0003","desc":"米蔵の脇にある大壁造の小規模な蔵で，切妻造，２階建，本瓦葺になる。切石の延べ石上に建ち，１・２階の腰壁を海鼠壁とするなど倉敷の蔵の基本的な形式をよく保っている。奥座敷㎡米蔵とともに奥庭を区画する配置となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000090"},{"id":"00000091","register_sub_id":"101","register_pk":"101081","name":"楠戸家住宅道具蔵","kana":"くすどけじゅうたくどうぐぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県倉敷市東町1-20","lat":34.59740543,"lng":133.77565103,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積18㎡","structure_material":"土蔵造2階建","registered":"1996.12.20(平成8.12.20)","register_no":"33 － 0004","desc":"主屋の奥座敷部分に接続する道具蔵は,炭蔵とほぼ同規模になるが,基底部は切石３段積みとなって，外壁も海鼠壁とする面積が広くなっている。他の蔵より一層重厚になる外観は，中庭の緑によく調和し落ち着いた屋敷構えを構成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000091"},{"id":"00000092","register_sub_id":"101","register_pk":"101082","name":"楠戸家住宅塀","kana":"くすどけじゅうたくへい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県倉敷市東町1-20","lat":34.59721815,"lng":133.77564938,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造、瓦葺、延長43m","structure_material":"木造","registered":"1996.12.20(平成8.12.20)","register_no":"33 － 0005","desc":"屋敷地の西側を画する屋根付きの板塀で，表通りの３間分は板張りとするが，敷地境の塀は腰下を切石積とし，上部をモルタル塗の新壁造とする。倉敷の明治期の上層町家の屋敷構えを構成する要素として重要である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000092"},{"id":"00012807","register_sub_id":"101","register_pk":"367710","name":"佐藤家住宅主屋","kana":"さとうけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"岡山県","address":"岡山県倉敷市福田町古新田字四之割294","lat":34.55027278,"lng":133.75343194,"geo_status":"db","era":"江戸中期／安政5年（1858）頃増築","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、茅葺（金属板仮葺）、建築面積191㎡","structure_material":"木造平屋建","registered":"2019.03.29(平成31.03.29)","register_no":"33 － 308","desc":"市南部の田園地帯の農家で、主屋は敷地中央に南面して建つ。東西棟の入母屋造茅葺（鉄板仮葺）で四周に本瓦葺の下屋を廻し、背面西端に座敷棟を付す。東に土間、西の前後に室を並べ、前列奧に座敷を設ける。備前地方平野部の伝統的な民家形式をよく示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012807"},{"id":"00012810","register_sub_id":"101","register_pk":"367713","name":"佐藤家住宅長屋門","kana":"さとうけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"岡山県","address":"岡山県倉敷市福田町古新田字四之割294","lat":34.55027278,"lng":133.75343194,"geo_status":"db","era":"安政5年(1858)／昭和40年頃改修","year":1858,"year_source":"db","year_min":1858,"year_max":1858,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積75㎡","structure_material":"木造平屋建","registered":"2019.03.29(平成31.03.29)","register_no":"33 － 311","desc":"敷地南面の東寄りに南面して建つ。入母屋造本瓦葺の平屋建で、背面に下屋を通す。外壁は真壁造の漆喰塗で、腰を縦板張とし、中央西寄りの門口に成の高い差物を渡す。門口の西は倉庫、東は控間付の座敷で正面に出格子を備える。旧家の表構えを重厚に整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012810"},{"id":"00012809","register_sub_id":"101","register_pk":"367712","name":"佐藤家住宅西土蔵","kana":"さとうけじゅうたくにしどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"岡山県","address":"岡山県倉敷市福田町古新田字四之割294","lat":34.55027278,"lng":133.75343194,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積33㎡","structure_material":"土蔵造2階建","registered":"2019.03.29(平成31.03.29)","register_no":"33 － 310","desc":"東土蔵西側に建つ家財蔵。土蔵造二階建、東西棟の切妻造本瓦葺で、南面西寄りと東面に戸口を設ける。外壁は漆喰塗で腰縦板張とする。内部は上下階とも板敷で、1階は東西二室に分け、2階は1室で、小屋は登梁とする。伝統的な屋敷構えを構成する要素である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012809"},{"id":"00012808","register_sub_id":"101","register_pk":"367711","name":"佐藤家住宅東土蔵","kana":"さとうけじゅうたくひがしどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県倉敷市福田町古新田字四之割294","lat":34.55027278,"lng":133.75343194,"geo_status":"db","era":"江戸末期／平成2年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積27㎡","structure_material":"土蔵造2階建","registered":"2019.03.29(平成31.03.29)","register_no":"33 － 309","desc":"主屋北側に南面して建つ道具蔵。土蔵造二階建、東西棟の切妻造本瓦葺で、正面に下屋を通し、西寄りに戸口を設ける。外壁は漆喰塗で腰と妻面を縦板張とする。上下階とも板敷で、小屋は登梁である。備前地方平野部の農家の伝統的な屋敷構えを構成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012808"},{"id":"00007691","register_sub_id":"101","register_pk":"108673","name":"清水家住宅主屋","kana":"しみずけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県津山市河辺字古屋敷889","lat":35.05913028,"lng":134.047241,"geo_status":"db","era":"明治後期／昭和45頃改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積216㎡","structure_material":"木造平屋建","registered":"2009.04.28(平成21.04.28)","register_no":"33 － 0230","desc":"敷地の北寄りに位置する。南面して建つ木造つし２階建、入母屋造桟瓦葺で東面は両下造屋根で納屋に接続し、西面には離れ座敷を付設する。右手を土間、左手を前後二列の床上部とし、前列西端にトコと棚を構える座敷とする。格子状に組まれた梁組は見応えがある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007691"},{"id":"00007693","register_sub_id":"101","register_pk":"108675","name":"清水家住宅土蔵","kana":"しみずけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県津山市河辺字古屋敷889","lat":35.059204,"lng":134.04715,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積33㎡","structure_material":"土蔵造2階建","registered":"2009.04.28(平成21.04.28)","register_no":"33 － 0232","desc":"主屋の西に東面して建つ。桁行８．５ｍ梁間３．９ｍの土蔵造２階建。切妻造桟瓦葺の置屋根とし、東面に奥行２．０ｍの下屋庇を付ける。外壁は漆喰仕上げで、妻と平で高さを違えて竪板を張る。当初は米殻が貯蔵された。装飾を抑えた質実な意匠である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007693"},{"id":"00007692","register_sub_id":"101","register_pk":"108674","name":"清水家住宅納屋","kana":"しみずけじゅうたくなや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県津山市河辺字古屋敷889","lat":35.05911683,"lng":134.04737186,"geo_status":"db","era":"明治後期／昭和後期改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積73㎡","structure_material":"木造2階建","registered":"2009.04.28(平成21.04.28)","register_no":"33 － 0231","desc":"主屋の東に南北棟で建つ。桁行１３ｍ梁間４．８ｍの木造２階建。入母屋造桟瓦葺で、東面北寄りと北面に庇を付ける。内部は、もとは南北に大きく分かれ、南側は倉庫と２階が居室、北側は馬・牛小屋で２階に干草など飼料が保管された。屋敷構えを構成する一施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007692"},{"id":"00007694","register_sub_id":"101","register_pk":"108676","name":"清水家住宅門及び井戸覆屋","kana":"しみずけじゅうたくもんおよびいどおおいや","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県津山市河辺字古屋敷889","lat":35.059044,"lng":134.04734086,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"門 木造、瓦葺、間口2.8m、井戸覆屋 木造、瓦葺、面積6.0㎡、井戸付","structure_material":"門 木造","registered":"2009.04.28(平成21.04.28)","register_no":"33 － 0233","desc":"納屋の南面に門が南北棟で続き、南に井戸覆屋が付く。ともに木造で、切妻造桟瓦葺。門は間口２．８ｍ。井戸覆屋は桁行３．０ｍ梁間２．０ｍで、南寄りに井戸を設ける。井戸は方形の角を取った八角形で、地元の凝灰岩製。出雲往来に面する敷地の表構えを整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007694"},{"id":"00000167","register_sub_id":"101","register_pk":"101157","name":"城東むかし町屋（旧梶村家住宅）表門","kana":"じょうとうむかしまちや（きゅうかじむらけじゅうたく）おもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"岡山県","address":"岡山県津山市東新町40","lat":35.06312501,"lng":134.01679717,"geo_status":"db","era":"大正時代","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正時代","structure":"棟門板塀付，瓦葺","structure_material":"棟門板塀付","registered":"1997.05.07(平成9.05.07)","register_no":"33 － 0013","desc":"主屋の西側に位置する一間棟門で，両脇に延びる一段高い屋根付きの袖塀に組み込まれた丁寧な造作になる。旧往還から一歩内側に入った位置に建ち，主屋や塀ととも町並みを形成している。なお，塀越しに見える樹木が城東の町並みに独特の風情を与えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000167"},{"id":"00000162","register_sub_id":"101","register_pk":"101152","name":"城東むかし町屋（旧梶村家住宅）座敷","kana":"じょうとうむかしまちや（きゅうかじむらけじゅうたく）ざしき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"岡山県","address":"岡山県津山市東新町40","lat":35.06328257,"lng":134.01675475,"geo_status":"db","era":"大正時代","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正時代","structure":"木造2階建，瓦葺，建築面積174㎡","structure_material":"木造2階建","registered":"1997.05.07(平成9.05.07)","register_no":"33 － 0008","desc":"敷地のほぼ中央部に，主屋の背後に接続して建つ二階建の大型の離れで，前後に一間幅の廊下が付く。屋根は入母屋造とし，背面を除く三方に庇が付く。良質の材料を用いた丁寧な仕上となる建物で，大正時代の洗練された技術や技法を知ることができる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000162"},{"id":"00000160","register_sub_id":"101","register_pk":"101150","name":"城東むかし町屋（旧梶村家住宅）主屋","kana":"じょうとうむかしまちや（きゅうかじむらけじゅうたく）しゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"岡山県","address":"岡山県津山市東新町40","lat":35.06322197,"lng":134.01691432,"geo_status":"db","era":"江戸時代末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸時代末期","structure":"木造2階建，瓦葺，建築面積211㎡","structure_material":"木造2階建","registered":"1997.05.07(平成9.05.07)","register_no":"33 － 0006","desc":"城東地区には，城下町津山を代表する商家の町並みが残っている。旧梶村家主屋は，間口８間半，奥行７間と大規模な町家で，居室部は３列系と推定される。江戸末期の建築と推定されるが，内部は大正時代に大改造された。全体的に質が高く風格ある建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000160"},{"id":"00000166","register_sub_id":"101","register_pk":"101156","name":"城東むかし町屋（旧梶村家住宅）茶室","kana":"じょうとうむかしまちや（きゅうかじむらけじゅうたく）ちゃしつ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"岡山県","address":"岡山県津山市東新町40","lat":35.06326237,"lng":134.01659921,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋建，スレート葺，建築面積11㎡","structure_material":"木造平屋建","registered":"1997.05.07(平成9.05.07)","register_no":"33 － 0012","desc":"屋敷地の西にあり，中庭を望む位置に建つ入母屋造の茶室で，「千草舎」の名がある。茶道に造詣のあった当主が，昭和の初期に庭の一画に造作したもので，小規模な造りながら吟味された材料を用いた上質の茶室で，技法的にも見るべきものがある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000166"},{"id":"00000165","register_sub_id":"101","register_pk":"101155","name":"城東むかし町屋（旧梶村家住宅）西蔵","kana":"じょうとうむかしまちや（きゅうかじむらけじゅうたく）にしぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"岡山県","address":"岡山県津山市東新町40","lat":35.06334317,"lng":134.01660123,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造2階建，瓦葺，建築面積25㎡","structure_material":"木造2階建","registered":"1997.05.07(平成9.05.07)","register_no":"33 － 0011","desc":"東蔵と並んで建つ土蔵で，外観の意匠は同様になる。東蔵に比べやや小振りであるが，棟高及び軒高を揃える一体的な造りになる。丁寧な造りになっており技術的にも見るべきものがある。他の建物とともに，大型商家の屋敷構えを知ることができる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000165"},{"id":"00000164","register_sub_id":"101","register_pk":"101154","name":"城東むかし町屋（旧梶村家住宅）東蔵","kana":"じょうとうむかしまちや（きゅうかじむらけじゅうたく）ひがしぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"岡山県","address":"岡山県津山市東新町40","lat":35.06336942,"lng":134.01667395,"geo_status":"db","era":"大正時代","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正時代","structure":"木造2階建，瓦葺，建築面積33㎡","structure_material":"木造2階建","registered":"1997.05.07(平成9.05.07)","register_no":"33 － 0010","desc":"敷地の背後に建つ伝統的な切妻造，桟瓦葺，大壁造の土蔵で，２棟ある蔵のうち東側にあることからその名が付く。漆喰仕上げの表面要所を海鼠壁とする外観は重厚で，軒廻りは３段に積み上げられた軒蛇腹で軒を飾る。大正期の土蔵造の技術の高さがうかがえる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000164"},{"id":"00000161","register_sub_id":"101","register_pk":"101151","name":"城東むかし町屋（旧梶村家住宅）付属屋","kana":"じょうとうむかしまちや（きゅうかじむらけじゅうたく）ふぞくや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"岡山県","address":"岡山県津山市東新町40","lat":35.06333711,"lng":134.01691432,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造平屋建，瓦葺，建築面積25㎡","structure_material":"木造平屋建","registered":"1997.05.07(平成9.05.07)","register_no":"33 － 0007","desc":"主屋の背後に接続する便所等の便益施設で，隣家との敷地境に沿って縦長に主屋から突き出す形で一体的に造られる。簡素な構えになるが，幕末から明治にかけての町家の居住空間を知る上でも意味深い付属建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000161"},{"id":"00000163","register_sub_id":"101","register_pk":"101153","name":"城東むかし町屋（旧梶村家住宅）洋館・裏座敷","kana":"じょうとうむかしまちや（きゅうかじむらけじゅうたく）ようかん・うらざしき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"岡山県","address":"岡山県津山市東新町40","lat":35.0634078,"lng":134.01677899,"geo_status":"db","era":"大正時代","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正時代","structure":"木造2階（一部平屋）建，瓦葺，建築面積85㎡","structure_material":"木造2階（一部平屋）建","registered":"1997.05.07(平成9.05.07)","register_no":"33 － 0009","desc":"座敷の裏手に建つドイツ壁仕上げの洋風の建物で，大正時代に家屋の改修時に建築されたもので，内部は当時流行した和洋併用の構えをしており，時代の特徴を表す遺構である。簡素な佇まいながら造作技法の質術は高く見るべきものがある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000163"},{"id":"00015509","register_sub_id":"101","register_pk":"533524","name":"瀬崎家住宅表門","kana":"せざきけじゅうたくおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県倉敷市真備町服部字辻󠄀堂914-1他","lat":34.61934722,"lng":133.67781389,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造、瓦葺、間口1.9m","structure_material":"木造","registered":"2025.08.06(令和7.08.06)","register_no":"33 - 0388","desc":"敷地の南面、松籟亭の東側に建つ門。切妻造平入本瓦葺で、南寄りに立てた本柱の前後に控柱を立て、正面側は冠木上から出した腕木で軒桁を支持し天井を張る。東西面の壁は漆喰塗仕上とし、腰は外を海鼠壁、内を竪板張とする。商家の繁栄を示す風格ある表門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015509"},{"id":"00015504","register_sub_id":"101","register_pk":"533519","name":"瀬崎家住宅主屋","kana":"せざきけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県倉敷市真備町服部字辻󠄀堂914-1他","lat":34.61948611,"lng":133.67770833,"geo_status":"db","era":"明治中期／昭和前期・同55年・令和3年改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積142㎡","structure_material":"木造2階建","registered":"2025.08.06(令和7.08.06)","register_no":"33 - 0383","desc":"小田川の右岸に位置する、廻船業や製糸業で栄えた商家の主屋。敷地中央に南面する二階建入母屋造平入本瓦葺で、正面中央に式台を構える。平面は六間取とし、南西に配する上の間は床脇に琵琶台を備えた端正な座敷で、四季の欄間彫刻など細部意匠にも優れる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015504"},{"id":"00015507","register_sub_id":"101","register_pk":"533522","name":"瀬崎家住宅北蔵","kana":"せざきけじゅうたくきたぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県倉敷市真備町服部字辻󠄀堂914-1他","lat":34.61948333,"lng":133.67783333,"geo_status":"db","era":"明治中期／令和3年改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積51㎡","structure_material":"土蔵造2階建","registered":"2025.08.06(令和7.08.06)","register_no":"33 - 0386","desc":"主屋の東に位置し、仕事道具を収納した土蔵。二階建切妻造桟瓦葺の南北棟で、外壁漆喰塗仕上。西面は庇を付し、東面の腰は竪板張とする。内部一階は北を土間、南に床構え付き座敷を配し、二階は一室の板敷とする。建ちの低い土蔵で敷地北東の景観を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015507"},{"id":"00015505","register_sub_id":"101","register_pk":"533520","name":"瀬崎家住宅松籟亭","kana":"せざきけじゅうたくしょうらいてい","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"岡山県","address":"岡山県倉敷市真備町服部字辻󠄀堂914-1他","lat":34.619325,"lng":133.67773333,"geo_status":"db","era":"明治中期／大正後期・令和3年改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積59㎡","structure_material":"木造平屋建","registered":"2025.08.06(令和7.08.06)","register_no":"33 - 0384","desc":"主屋の南側、敷地の南端に建つ寄棟造桟瓦葺東西棟の茶室。縁を付した四畳半切の七畳広間は、皮付マツの床柱を用いた袋床や三角棚、丸窓を備え、駆込み天井を張る。水屋を置く続き間六畳とは下地窓付の凝った襖壁で画す。開放的で意匠性に富んだ華やかな茶室。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015505"},{"id":"00015510","register_sub_id":"101","register_pk":"533525","name":"瀬崎家住宅中門及び塀","kana":"せざきけじゅうたくなかもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"岡山県","address":"岡山県倉敷市真備町服部字辻󠄀堂914-1他","lat":34.61939722,"lng":133.67770278,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"中門 木造、瓦葺、間口1.3m、袖塀付 塀 木造、瓦葺、総延長8.5m","structure_material":"中門 木造","registered":"2025.08.06(令和7.08.06)","register_no":"33 - 0389","desc":"主屋の南方に設けた中門及び塀。中門は切妻造本瓦葺の腕木門で門口に一枚板の板戸を引分に建てる。中門の両脇から矩折れに延びる塀は屋根桟瓦葺で壁は漆喰塗仕上とし、中門の腰を竪板張とする以外はモルタル洗出仕上。敷地の西側を画し、庭園への動線を演出。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015510"},{"id":"00015506","register_sub_id":"101","register_pk":"533521","name":"瀬崎家住宅如是庵","kana":"せざきけじゅうたくにょぜあん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"岡山県","address":"岡山県倉敷市真備町服部字辻󠄀堂914-1他","lat":34.61942222,"lng":133.67750278,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、茅葺、建築面積22㎡","structure_material":"木造平屋建","registered":"2025.08.06(令和7.08.06)","register_no":"33 - 0385","desc":"敷地西辺に位置する茶室。入母屋造茅葺で東面に腰掛待合を備え、西側の廊下を塀外に張り出す。一畳台目二畳中板の小間は、中柱と下部吹放ちの袖壁で点前座を画す。天井は点前座を蒲天井、客座を網代編天井とする掛込天井。間取に趣向を凝らした独創的な茶室。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015506"},{"id":"00015508","register_sub_id":"101","register_pk":"533523","name":"瀬崎家住宅南蔵","kana":"せざきけじゅうたくみなみぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県倉敷市真備町服部字辻󠄀堂914-1他","lat":34.61941389,"lng":133.67784167,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積69㎡","structure_material":"土蔵造2階建","registered":"2025.08.06(令和7.08.06)","register_no":"33 - 0387","desc":"北蔵の南側に接続し、茶道具や家財道具を納める土蔵。二階建切妻造桟瓦葺の南北棟で、西面は庇を付し、腰は海鼠壁仕上、他三面は腰を竪板張で水切や隅部を瓦貼とする。一階は二室、二階は一室でいずれも板敷とする。重厚な外観が屋敷景観に寄与する土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015508"},{"id":"00012450","register_sub_id":"101","register_pk":"531774","name":"仙田家住宅主屋","kana":"せんだけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"岡山県","address":"岡山県倉敷市藤戸町天城字町96","lat":34.56221111,"lng":133.809925,"geo_status":"db","era":"江戸末期／昭和50年・同56年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積120㎡","structure_material":"木造2階建","registered":"2018.05.10(平成30.05.10)","register_no":"33-296","desc":"倉敷市郊外の天城にある小売業を営んだ商家。街道に面した切妻造本瓦葺平入の主屋は、内部が改変されているが、一階を開口部、二階を漆喰塗とする正面や海鼠壁等が伝統的な形式をよく残している。現在は診療所として地域に親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012450"},{"id":"00010048","register_sub_id":"101","register_pk":"196195","name":"竹本家住宅主屋","kana":"たけもとけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県新見市千屋実字オホマヘ619","lat":35.13535868,"lng":133.42650458,"geo_status":"db","era":"明治30頃／平成3頃改修","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積182㎡","structure_material":"木造平屋一部2階建","registered":"2014.04.25(平成26.04.25)","register_no":"33 － 0253","desc":"敷地ほぼ中央に東面して建つ。入母屋造桟瓦葺で下屋を四周に廻す。外壁は漆喰塗とするが、赤や青の色漆喰を用いたり、腰に海鼠壁風、北東隅に柱形風の漆喰彫刻などを施し、豊かな装飾を見せる。内部は座敷、広間の天井が高く、備中神楽を奉納したという。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010048"},{"id":"00010049","register_sub_id":"101","register_pk":"196196","name":"竹本家住宅長屋及び米蔵","kana":"たけもとけじゅうたくながやおよびこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県新見市千屋実字オホマヘ619","lat":35.13524204,"lng":133.42663712,"geo_status":"db","era":"明治30頃／平成3頃改修","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"木造及び土蔵造2階建、瓦葺、建築面積63㎡","structure_material":"木造及び土蔵造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"33 － 0254","desc":"敷地南東隅に建つ二階建、切妻造桟瓦葺の建物。北寄り三間半を真壁造の長屋、南寄り二間を土蔵造の米蔵とする。外観は長屋の腰部と米蔵一階は簓子下見板張、上部は漆喰塗とするが、腰上に松皮菱をあしらった帯を廻らせるなど、左官仕事により意匠を凝らす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010049"}];
